/* PROSRC LINES COUNT */
--ReqID:SRS-SQL-PACKAGE
--use dynamic sql to support package
CREATE OR REPLACE FUNCTION SYS._ORA_SRC_COUNT(objectid OID,table_name TEXT,
src_name text)
RETURNS INTEGER AS $$
DECLARE
	RET INTEGER;
	stmt_query text;
BEGIN
   /* Begin - BUG#Z370 */
   IF (table_name = 'PG_PROC') THEN
      stmt_query := 'SELECT COUNT(1) from (SELECT UNNEST(STRING_TO_ARRAY(pg_get_functiondef(' || objectid || ')'|| ',CHR(10)))) AS SQ';
   ELSE
   /* End - BUG#Z370 */
     stmt_query := 'SELECT COUNT(1) FROM (SELECT UNNEST(STRING_TO_ARRAY(' || src_name || ',CHR(10)))' ||
       ' FROM ' || table_name || ' WHERE oid = ' || objectid || ') AS SQ';
   /* Begin - BUG#Z370 */
   END IF;
   /* End - BUG#Z370 */

   EXECUTE stmt_query INTO RET;
   RETURN RET;
END;
$$ LANGUAGE PLPGSQL IMMUTABLE;

/* DBA_SOURCE */
/* Begin - ReqID:SRS-SQL-PACKAGE */
--use proc_source
CREATE OR REPLACE VIEW SYS.DBA_PROC_SOURCE AS
SELECT
	SYS.ORA_CASE_TRANS(
		PG_GET_USERBYID(P.PROOWNER)::VARCHAR2
	)::VARCHAR2(128) AS OWNER,
	SYS.ORA_CASE_TRANS(P.PRONAME::VARCHAR2)::VARCHAR2(128) AS NAME,
	CASE
		WHEN P.PROKIND = 'f'
			THEN 'FUNCTION'
		ELSE 'PROCEDURE'
	END::VARCHAR2(12) AS TYPE,
	GENERATE_SERIES(1::INTEGER, SYS._ORA_SRC_COUNT(P.OID, 'PG_PROC', 'PROSRC'))::NUMBER AS LINE,
	UNNEST(STRING_TO_ARRAY(substring(pg_get_functiondef(P.OID), length('CREATE OR REPLACE ') + 1), CHR(10)))::VARCHAR2(4000) AS TEXT,
	0::VARCHAR2(256) AS ORIGIN_CON_ID
FROM
	PG_PROC AS P
	LEFT JOIN PG_TRIGGER AS T
		ON P.OID = T.TGFOID
WHERE
	P.PROKIND = ANY(ARRAY['p', 'f'])
	AND T.OID IS NULL
	AND P.PRONAMESPACE <> 'PG_CATALOG'::REGNAMESPACE::OID
	AND P.PRONAMESPACE <> 'PG_TOAST'::REGNAMESPACE::OID
	AND P.PRONAMESPACE <> 'INFORMATION_SCHEMA'::REGNAMESPACE::OID
;

GRANT SELECT ON SYS.DBA_PROC_SOURCE TO PUBLIC;

--interle include extral some cols which will be
--used in others view about package
CREATE OR REPLACE VIEW SYS.DBA_PACKAGE_SPEC_SOURCE_INTERNEL AS
SELECT
    P.PKGOWNER AS OWNER_ID,
	P.OID,
	P.PKGNAMESPACE AS NAMESPACE_ID,
	SYS.ORA_CASE_TRANS(
		PG_GET_USERBYID(P.PKGOWNER)::VARCHAR2
	)::VARCHAR2(128) AS OWNER,
	SYS.ORA_CASE_TRANS(P.PKGNAME::VARCHAR2)::VARCHAR2(128) AS NAME,
	'PACKAGE'::VARCHAR2(12) AS TYPE,
	GENERATE_SERIES(1::INTEGER, SYS._ORA_SRC_COUNT(P.OID,'PG_PACKAGE', 'PKGSRC') + 1)::NUMBER AS LINE,
	UNNEST(STRING_TO_ARRAY('PACKAGE '  || SYS.ORA_CASE_TRANS(P.PKGNAME::VARCHAR2) ||' IS' || CHR(10) || P.PKGSRC
	  /* Begin - BUG#Z369 */
	  || ';'
	  /* End - BUG#Z369 */
	  , CHR(10)))::VARCHAR2(4000) AS TEXT,
	  0::VARCHAR2(256) AS ORIGIN_CON_ID
FROM
	PG_PACKAGE AS P
WHERE
	P.PKGNAMESPACE <> 'PG_CATALOG'::REGNAMESPACE::OID
	AND P.PKGNAMESPACE <> 'PG_TOAST'::REGNAMESPACE::OID
	AND P.PKGNAMESPACE <> 'INFORMATION_SCHEMA'::REGNAMESPACE::OID
;

--grant it to public
GRANT SELECT ON SYS.DBA_PACKAGE_SPEC_SOURCE_INTERNEL TO PUBLIC;

CREATE OR REPLACE VIEW SYS.DBA_PACKAGE_BODY_SOURCE_INTERNEL AS
SELECT
    P1.PKGOWNER AS OWNER_ID,
	P1.OID,
	P1.PKGNAMESPACE AS NAMESPACE_ID,
	SYS.ORA_CASE_TRANS(
		PG_GET_USERBYID(P1.PKGOWNER)::VARCHAR2
	)::VARCHAR2(128) AS OWNER,
	SYS.ORA_CASE_TRANS(P1.PKGNAME::VARCHAR2)::VARCHAR2(128) AS NAME,
	'PACKAGE BODY'::VARCHAR2(12) AS TYPE,
	GENERATE_SERIES(1::INTEGER, SYS._ORA_SRC_COUNT(P.OID,'PG_PACKAGE_BODY', 'BODYSRC') + 1)::NUMBER AS LINE,
	UNNEST(STRING_TO_ARRAY('PACKAGE BODY '  || SYS.ORA_CASE_TRANS(P1.PKGNAME::VARCHAR2) ||' IS' || CHR(10) || P.BODYSRC
	  /* Begin - BUG#Z369 */
	  || ';'
	  /* End - BUG#Z369 */
	  , CHR(10)))::VARCHAR2(4000) AS TEXT,
	  0::VARCHAR2(256) AS ORIGIN_CON_ID
FROM
	PG_PACKAGE_BODY AS P LEFT JOIN PG_PACKAGE AS P1
	ON P.PKGOID = P1.OID
WHERE
	P1.PKGNAMESPACE <> 'PG_CATALOG'::REGNAMESPACE::OID
	AND P1.PKGNAMESPACE <> 'PG_TOAST'::REGNAMESPACE::OID
	AND P1.PKGNAMESPACE <> 'INFORMATION_SCHEMA'::REGNAMESPACE::OID
;

GRANT SELECT ON SYS.DBA_PACKAGE_BODY_SOURCE_INTERNEL TO PUBLIC;

--object type source internal views
CREATE OR REPLACE VIEW SYS.DBA_OBJTYPE_SOURCE_INTERNEL AS
SELECT
	ot.objowner AS OWNER_ID,
	ot.oid,
	ot.objnamespace AS NAMESPACE_ID,
	SYS.ORA_CASE_TRANS(
		PG_GET_USERBYID(ot.objowner)::VARCHAR2
	)::VARCHAR2(128) AS OWNER,
	SYS.ORA_CASE_TRANS(t.typname::VARCHAR2)::VARCHAR2(128) AS NAME,
	'TYPE'::VARCHAR2(12) AS TYPE,
	GENERATE_SERIES(1::INTEGER, SYS._ORA_SRC_COUNT(ot.oid, 'PG_OBJECT_TYPE', 'OBJSRC'))::NUMBER AS LINE,
	UNNEST(STRING_TO_ARRAY(ot.objsrc, CHR(10)))::VARCHAR2(4000) AS TEXT,
	0::VARCHAR2(256) AS ORIGIN_CON_ID
FROM
	pg_object_type ot
LEFT JOIN
	pg_type t ON ot.typid = t.oid
WHERE
	ot.objnamespace <> 'PG_CATALOG'::REGNAMESPACE::OID
	AND ot.objnamespace <> 'PG_TOAST'::REGNAMESPACE::OID
	AND ot.objnamespace <> 'INFORMATION_SCHEMA'::REGNAMESPACE::OID
;

GRANT SELECT ON SYS.DBA_OBJTYPE_SOURCE_INTERNEL TO PUBLIC;

CREATE OR REPLACE VIEW SYS.DBA_OBJTYPE_BODY_SOURCE_INTERNEL AS
SELECT
	ot.objowner AS OWNER_ID,
	ot.oid,
	ot.objnamespace AS NAMESPACE_ID,
	SYS.ORA_CASE_TRANS(
		PG_GET_USERBYID(ot.objowner)::VARCHAR2
	)::VARCHAR2(128) AS OWNER,
	SYS.ORA_CASE_TRANS(t.typname::VARCHAR2)::VARCHAR2(128) AS NAME,
	'TYPE BODY'::VARCHAR2(12) AS TYPE,
	GENERATE_SERIES(1::INTEGER, SYS._ORA_SRC_COUNT(otb.oid, 'PG_OBJECT_TYPE_BODY', 'BODYSRC'))::NUMBER AS LINE,
	UNNEST(STRING_TO_ARRAY(otb.bodysrc, CHR(10)))::VARCHAR2(4000) AS TEXT,
	0::VARCHAR2(256) AS ORIGIN_CON_ID
FROM
	pg_object_type_body otb
LEFT JOIN
	pg_object_type ot ON otb.objtypoid = ot.oid
LEFT JOIN
	pg_type t ON ot.typid = t.oid
WHERE
	ot.objnamespace <> 'PG_CATALOG'::REGNAMESPACE::OID
	AND ot.objnamespace <> 'PG_TOAST'::REGNAMESPACE::OID
	AND ot.objnamespace <> 'INFORMATION_SCHEMA'::REGNAMESPACE::OID
;

GRANT SELECT ON SYS.DBA_OBJTYPE_BODY_SOURCE_INTERNEL TO PUBLIC;

CREATE OR REPLACE VIEW SYS.DBA_OBJTYPE_SOURCE AS
	(SELECT OWNER,NAME,TYPE,LINE,TEXT,ORIGIN_CON_ID FROM
	SYS.DBA_OBJTYPE_SOURCE_INTERNEL)
UNION ALL
	(SELECT OWNER,NAME,TYPE,LINE,TEXT,ORIGIN_CON_ID FROM
	SYS.DBA_OBJTYPE_BODY_SOURCE_INTERNEL);

GRANT SELECT ON SYS.DBA_OBJTYPE_SOURCE TO PUBLIC;

CREATE OR REPLACE VIEW SYS.DBA_PACKAGE_SOURCE AS
	(SELECT OWNER,NAME,TYPE,LINE,TEXT,ORIGIN_CON_ID FROM
   SYS.DBA_PACKAGE_SPEC_SOURCE_INTERNEL) --come from pg_package
UNION ALL
	(SELECT OWNER,NAME,TYPE,LINE,TEXT,ORIGIN_CON_ID FROM
	SYS.DBA_PACKAGE_BODY_SOURCE_INTERNEL); --come from pg_package_body

GRANT SELECT ON SYS.DBA_PACKAGE_SOURCE TO PUBLIC;

CREATE OR REPLACE VIEW SYS.DBA_SOURCE AS
	SELECT * FROM SYS.DBA_PROC_SOURCE --come from functions or procedures
UNION ALL
	SELECT * FROM SYS.DBA_PACKAGE_SOURCE	--come from packages
UNION ALL
	SELECT * FROM SYS.DBA_OBJTYPE_SOURCE;	--come from object types
/* End - ReqID:SRS-SQL-PACKAGE */

/* GRANT SELECT PRIVILEGE TO PUBLIC */
GRANT SELECT ON SYS.DBA_SOURCE TO PUBLIC;

/* ALL_SOURCE */
CREATE OR REPLACE VIEW SYS.ALL_PROC_SOURCE AS
SELECT
	SYS.ORA_CASE_TRANS(
		PG_GET_USERBYID(P.PROOWNER)::VARCHAR2
	)::VARCHAR2(128) AS OWNER,
	SYS.ORA_CASE_TRANS(P.PRONAME::VARCHAR2)::VARCHAR2(128) AS NAME,
	CASE
		WHEN P.PROKIND = 'f'
			THEN 'FUNCTION'
		ELSE 'PROCEDURE'
	END::VARCHAR2(12) AS TYPE,
	GENERATE_SERIES(1::INTEGER, SYS._ORA_SRC_COUNT(P.OID, 'PG_PROC', 'PROSRC'))::NUMBER AS LINE,
	UNNEST(STRING_TO_ARRAY(substring(pg_get_functiondef(P.OID), length('CREATE OR REPLACE ') + 1), CHR(10)))::VARCHAR2(4000) AS TEXT,
	0::VARCHAR2(256) AS ORIGIN_CON_ID
FROM
	PG_PROC AS P
	LEFT JOIN PG_TRIGGER AS T
		ON P.OID = T.TGFOID
WHERE
	P.PROKIND = ANY(ARRAY['p', 'f'])
	AND T.OID IS NULL
	AND P.PRONAMESPACE <> 'PG_CATALOG'::REGNAMESPACE::OID
	AND P.PRONAMESPACE <> 'PG_TOAST'::REGNAMESPACE::OID
	AND P.PRONAMESPACE <> 'INFORMATION_SCHEMA'::REGNAMESPACE::OID
	AND HAS_SCHEMA_PRIVILEGE(P.PRONAMESPACE, 'USAGE')	/* BUG#Z169 */
	AND HAS_FUNCTION_PRIVILEGE(P.OID, 'EXECUTE')
;

GRANT SELECT ON SYS.ALL_PROC_SOURCE TO PUBLIC;
/* Begin - ReqID:SRS-SQL-PACKAGE */
CREATE OR REPLACE VIEW SYS.ALL_PACKAGE_SOURCE AS
	(SELECT OWNER, NAME,TYPE,
   LINE,TEXT,ORIGIN_CON_ID FROM SYS.DBA_PACKAGE_SPEC_SOURCE_INTERNEL P
   WHERE HAS_SCHEMA_PRIVILEGE(P.NAMESPACE_ID, 'USAGE') AND
	HAS_PACKAGE_PRIVILEGE(P.OID, 'EXECUTE')) --come from pg_package
UNION ALL
	(SELECT OWNER,NAME,TYPE,LINE,
	TEXT,ORIGIN_CON_ID FROM SYS.DBA_PACKAGE_BODY_SOURCE_INTERNEL P
	WHERE HAS_SCHEMA_PRIVILEGE(P.NAMESPACE_ID, 'USAGE') AND
	HAS_PACKAGE_PRIVILEGE(P.OID, 'EXECUTE')); --come from pg_package_body

GRANT SELECT ON SYS.ALL_PACKAGE_SOURCE TO PUBLIC;

CREATE OR REPLACE VIEW SYS.ALL_OBJTYPE_SOURCE AS
	(SELECT OWNER, NAME,TYPE,
	LINE,TEXT,ORIGIN_CON_ID FROM SYS.DBA_OBJTYPE_SOURCE_INTERNEL P
	WHERE HAS_SCHEMA_PRIVILEGE(P.NAMESPACE_ID, 'USAGE'))
UNION ALL
	(SELECT OWNER,NAME,TYPE,LINE,
	TEXT,ORIGIN_CON_ID FROM SYS.DBA_OBJTYPE_BODY_SOURCE_INTERNEL P
	WHERE HAS_SCHEMA_PRIVILEGE(P.NAMESPACE_ID, 'USAGE'));

GRANT SELECT ON SYS.ALL_OBJTYPE_SOURCE TO PUBLIC;

CREATE OR REPLACE VIEW SYS.ALL_SOURCE AS
	SELECT * FROM SYS.ALL_PROC_SOURCE --come from procedures or functions
UNION ALL
	SELECT * FROM SYS.ALL_PACKAGE_SOURCE --come from packages
UNION ALL
	SELECT * FROM SYS.ALL_OBJTYPE_SOURCE; --come from object types
/* End - ReqID:SRS-SQL-PACKAGE */

/* GRANT SELECT PRIVILEGE TO PUBLIC */
GRANT SELECT ON SYS.ALL_SOURCE TO PUBLIC;

/* USER_SOURCE */
CREATE OR REPLACE VIEW SYS.USER_PROC_SOURCE AS
SELECT
	SYS.ORA_CASE_TRANS(P.PRONAME::VARCHAR2)::VARCHAR2(128) AS NAME,
	CASE
		WHEN P.PROKIND = 'f'
			THEN 'FUNCTION'
		ELSE 'PROCEDURE'
	END::VARCHAR2(12) AS TYPE,
	GENERATE_SERIES(1::INTEGER, SYS._ORA_SRC_COUNT(P.OID, 'PG_PROC', 'PROSRC'))::NUMBER AS LINE,
	UNNEST(STRING_TO_ARRAY(substring(pg_get_functiondef(P.OID), length('CREATE OR REPLACE ') + 1), CHR(10)))::VARCHAR2(4000) AS TEXT,
	0::VARCHAR2(256) AS ORIGIN_CON_ID
FROM
	PG_PROC AS P
	LEFT JOIN PG_TRIGGER AS T
		ON P.OID = T.TGFOID
WHERE
	P.PROKIND = ANY(ARRAY['p', 'f'])
	AND T.OID IS NULL
	AND P.PRONAMESPACE <> 'PG_CATALOG'::REGNAMESPACE::OID
	AND P.PRONAMESPACE <> 'PG_TOAST'::REGNAMESPACE::OID
	AND P.PRONAMESPACE <> 'INFORMATION_SCHEMA'::REGNAMESPACE::OID
	AND PG_GET_USERBYID(P.PROOWNER) = CURRENT_USER	/* BUG#M0000074 */
;

GRANT SELECT ON SYS.USER_PROC_SOURCE TO PUBLIC;

/* Begin - ReqID:SRS-SQL-PACKAGE */
CREATE OR REPLACE VIEW SYS.USER_PACKAGE_SOURCE AS
	(SELECT NAME,TYPE,
   LINE,TEXT,ORIGIN_CON_ID FROM SYS.DBA_PACKAGE_SPEC_SOURCE_INTERNEL P
   WHERE PG_GET_USERBYID(P.OWNER_ID) = CURRENT_USER) /* BUG#M0000074 */ --come from pg_package
UNION ALL
	(SELECT NAME,TYPE,LINE,
	TEXT,ORIGIN_CON_ID FROM SYS.DBA_PACKAGE_BODY_SOURCE_INTERNEL P
	WHERE PG_GET_USERBYID(P.OWNER_ID) = CURRENT_USER); /* BUG#M0000074 */ --come from pg_package_body

GRANT SELECT ON SYS.USER_PACKAGE_SOURCE TO PUBLIC;

CREATE OR REPLACE VIEW SYS.USER_OBJTYPE_SOURCE AS
	(SELECT NAME,TYPE,
	LINE,TEXT,ORIGIN_CON_ID FROM SYS.DBA_OBJTYPE_SOURCE_INTERNEL P
	WHERE PG_GET_USERBYID(P.OWNER_ID) = CURRENT_USER)
UNION ALL
	(SELECT NAME,TYPE,LINE,
	TEXT,ORIGIN_CON_ID FROM SYS.DBA_OBJTYPE_BODY_SOURCE_INTERNEL P
	WHERE PG_GET_USERBYID(P.OWNER_ID) = CURRENT_USER);

GRANT SELECT ON SYS.USER_OBJTYPE_SOURCE TO PUBLIC;

CREATE OR REPLACE VIEW SYS.USER_SOURCE AS
  SELECT * FROM SYS.USER_PROC_SOURCE --come from functions or procedures
UNION ALL
  SELECT * FROM SYS.USER_PACKAGE_SOURCE --come from packages
UNION ALL
  SELECT * FROM SYS.USER_OBJTYPE_SOURCE; --come from object types
/* End - ReqID:SRS-SQL-PACKAGE */

/* GRANT SELECT PRIVILEGE TO PUBLIC */
GRANT SELECT ON SYS.USER_SOURCE TO PUBLIC;

/* ARGUMENTS' TYPE COUNT */
CREATE OR REPLACE FUNCTION SYS._ORA_ARGS_COUNT(PROID OID)
RETURNS INTEGER
AS $$
DECLARE
	RET INTEGER;
BEGIN
	SELECT
		COUNT(1)
	FROM
	(
		SELECT
			UNNEST(
				CASE
					WHEN PROALLARGTYPES IS NOT NULL
						THEN PROALLARGTYPES
					ELSE PROARGTYPES
				END
			)
		FROM
			PG_PROC
		WHERE OID = $1
	) AS SQ
	INTO
		RET;
	RETURN RET;
END;
$$ LANGUAGE PLPGSQL IMMUTABLE;

/* DBA_ARGUMENTS */
CREATE OR REPLACE VIEW SYS.DBA_PROC_ARGUMENTS AS
SELECT
	SYS.ORA_CASE_TRANS(
		PG_GET_USERBYID(P.PROOWNER)::VARCHAR2
	)::VARCHAR2(128) AS OWNER,
	SYS.ORA_CASE_TRANS(P.PRONAME::VARCHAR2)::VARCHAR2(128) AS OBJECT_NAME,
	NULL::VARCHAR2(128) AS PACKAGE_NAME,
	P.OID::VARCHAR2(10)::NUMBER AS OBJECT_ID,
	NULL::VARCHAR2(40) AS OVERLOAD,
	1::NUMBER AS SUBPROGRAM_ID,
	SYS.ORA_CASE_TRANS(
		SQ.ARGUMENT_NAME::VARCHAR2
	)::VARCHAR2(128) AS ARGUMENT_NAME,
	SQ.POSITION::NUMBER AS POSITION,
	CASE
		WHEN P.PROKIND = 'f'
			THEN SQ.POSITION + 1
		ELSE SQ.POSITION
	END::NUMBER AS SEQUENCE,
	0::NUMBER AS DATA_LEVEL,
	CASE
	    /* Begin - ReqID:SRS-PLSQL-TYPE */
		WHEN ARG.TYPE_OBJECT_TYPE::VARCHAR2 = 'table' OR ARG.TYPE_OBJECT_TYPE::VARCHAR2 = 'TABLE'
		  OR ARG.TYPE_OBJECT_TYPE::VARCHAR2 = 'view' OR ARG.TYPE_OBJECT_TYPE::VARCHAR2 = 'VIEW'
		  THEN 'PL/SQL RECORD'
		/* End - ReqID:SRS-PLSQL-TYPE */
		WHEN T.TYPNAME = ANY(ARRAY['int2', 'int4', 'int8',
								   'numeric', 'number'])
			THEN 'NUMBER'
		WHEN T.TYPNAME = ANY(ARRAY['float4', 'float8'])
			THEN 'FLOAT'
		WHEN T.TYPNAME = 'bpchar'
			THEN 'CHAR'
		/* Begin - ReqID:SRS-PLSQL-RECORD */
		WHEN T.TYPNAME = 'orarecord'
		  THEN 'PL/SQL RECORD'
		/* End - ReqID:SRS-PLSQL-RECORD */
		ELSE ORA_CASE_TRANS(T.OID::REGTYPE::VARCHAR2)::VARCHAR2(58)
	END::VARCHAR2(30) AS DATA_TYPE,
	/* Begin - BUG#Z170 */
	CASE
		WHEN PG_GET_FUNCTION_ARG_DEFAULT(SQ.OID, SQ.POSITION) IS NULL
			THEN 'N'
		ELSE 'Y'
	END::VARCHAR2(1) AS DEFAULTED,
	/* End - BUG#Z170 */
	NULL::LONG AS DEFAULT_VALUE,
	NULL::NUMBER AS DEFAULT_LENGTH,
	CASE
		WHEN SQ.IN_OUT = 'i' OR SQ.IN_OUT IS NULL
			THEN 'IN'
		WHEN SQ.IN_OUT = 'o'
			THEN 'OUT'
		WHEN SQ.IN_OUT = 'b'
			THEN 'IN/OUT'
		ELSE NULL
	END::VARCHAR2(9) AS IN_OUT,
	CASE
		/* Begin - ReqID:SRS-PLSQL-TYPE */
		WHEN ARG.DATA_LENGTH IS NOT NULL
		    THEN ARG.DATA_LENGTH
		/* End - ReqID:SRS-PLSQL-TYPE */
		WHEN T.TYPNAME = ANY(ARRAY['int2', 'int4', 'int8',
								   'float4', 'float8',
								   'numeric', 'number'])
			THEN 22
		WHEN T.TYPNAME = ANY(ARRAY['long', 'long_raw'])
			THEN 32760
		ELSE NULL
	END::NUMBER AS DATA_LENGTH,
	CASE
		/* Begin - ReqID:SRS-PLSQL-TYPE */
		WHEN ARG.DATA_PRECISION IS NOT NULL
		    THEN ARG.DATA_PRECISION
		/* End - ReqID:SRS-PLSQL-TYPE */
		WHEN T.TYPNAME = ANY(ARRAY['int2', 'int4', 'int8'])
			THEN 38
		WHEN T.TYPNAME = 'float4'
			THEN 63
		WHEN T.TYPNAME = 'float8'
			THEN 126
		WHEN T.TYPNAME = ANY(ARRAY['timestamp', 'timestamptz',
								   'oratimestamp', 'oratimestamptz',
								   'oratimestampltz'])
			THEN 6
		ELSE NULL
	END::NUMBER AS DATA_PRECISION,
	CASE
		/* Begin - ReqID:SRS-PLSQL-TYPE */
		WHEN ARG.DATA_SCALE IS NOT NULL
		    THEN ARG.DATA_SCALE
		/* End - ReqID:SRS-PLSQL-TYPE */
		WHEN T.TYPNAME = ANY(ARRAY['float4', 'float8'])
			THEN -127
		ELSE NULL
	END::NUMBER AS DATA_SCALE,
	CASE
		WHEN T.TYPNAME = ANY(ARRAY['numeric', 'number',
								   'int2', 'int4', 'int8',
								   'float4', 'float8'])
			THEN 10
		ELSE NULL
	END::NUMBER AS RADIX,
	CASE
		WHEN T.OID::REGTYPE::VARCHAR2(58) = ANY(ARRAY['char',
													  'character',
													  'varchar2',
													  'clob'])
			THEN 'CHAR_CS'
		WHEN T.OID::REGTYPE::VARCHAR2(58) = ANY(ARRAY['nchar', 'nvarchar2',
													  'nclob'])
			THEN 'NCHAR_CS'
	END::VARCHAR2(44) AS CHARACTER_SET_NAME,
	NULL::VARCHAR2(128) AS TYPE_OWNER,
	/* Begin - ReqID:SRS-PLSQL-TYPE */
	CASE
	   WHEN ARG.TYPE_NAME != '_NULL_'
	        THEN SYS.ORA_CASE_TRANS(ARG.TYPE_NAME::VARCHAR2)::VARCHAR2(128)
	   ELSE
	        NULL
	END::VARCHAR2(128) AS TYPE_NAME,
	CASE
	   WHEN ARG.TYPE_SUBNAME != '_NULL_'
	        THEN SYS.ORA_CASE_TRANS(ARG.TYPE_SUBNAME::VARCHAR2)::VARCHAR2(128)
	   ELSE
	        NULL
	END::VARCHAR2(128) AS TYPE_SUBNAME,
	/* End - ReqID:SRS-PLSQL-TYPE */
	NULL::VARCHAR2(128) AS TYPE_LINK,
	/* Begin - ReqID:SRS-PLSQL-TYPE */
	CASE
	   WHEN ARG.TYPE_OBJECT_TYPE != '_NULL_'
	        THEN SYS.ORA_CASE_TRANS(ARG.TYPE_OBJECT_TYPE::VARCHAR2)::VARCHAR2(128)
	   ELSE
	        NULL
	END::VARCHAR2(128) AS TYPE_OBJECT_TYPE,
    /* End - ReqID:SRS-PLSQL-TYPE */
	CASE
		WHEN (T.TYPTYPE = 'b' OR T.TYPTYPE = 'c') AND ARG.PLS_TYPE IS NOT NULL
			THEN SYS.ORA_CASE_TRANS(ARG.PLS_TYPE)
		WHEN T.TYPTYPE = 'b' AND ARG.PLS_TYPE IS NULL
			THEN SYS.ORA_CASE_TRANS(T.OID::REGTYPE::VARCHAR2)
		WHEN T.TYPTYPE = 'd' AND T.TYPNAME = 'raw'
			THEN 'RAW'
		WHEN T.TYPTYPE = 'd' AND T.TYPNAME = 'blob'
			THEN 'BLOB'
		WHEN T.TYPTYPE = 'd' AND T.TYPNAME = 'clob'
			THEN 'CLOB'
		WHEN T.TYPTYPE = 'd' AND T.TYPNAME = 'nclob'
			THEN 'CLOB'
		WHEN T.TYPTYPE = 'd' AND T.TYPNAME = 'long'
			THEN 'LONG'
		WHEN T.TYPTYPE = 'd' AND T.TYPNAME = 'long_raw'
			THEN 'LONG_RAW'
		ELSE NULL
	END::VARCHAR2(30) AS PLS_TYPE,
	CASE
		WHEN T.OID::REGTYPE::VARCHAR2(58) = ANY(ARRAY['char',
													  'character',
													  'varchar2'])
			THEN NULL
		ELSE 0
	END::NUMBER AS CHAR_LENGTH,
	CASE
		WHEN T.OID::REGTYPE::VARCHAR2(58) = ANY(ARRAY['char',
													  'character',
													  'varchar2'])
			THEN 'B'
		ELSE '0'
	END::VARCHAR2(1) AS CHAR_USED,
	0::VARCHAR2(256) AS ORIGIN_CON_ID
FROM
	PG_PROC AS P
	LEFT JOIN
	(
		SELECT
			OID,
			NULL AS ARGUMENT_NAME,
			PRORETTYPE AS DATA_TYPE,
			'o' AS IN_OUT,
			0 AS POSITION
		FROM
			PG_PROC
		WHERE
			PROKIND = 'f'
		UNION ALL
		SELECT
			OID,
			UNNEST(PROARGNAMES) AS ARGUMENT_NAME,
			UNNEST(
			CASE
				WHEN PROALLARGTYPES IS NOT NULL
					THEN PROALLARGTYPES
				ELSE PROARGTYPES
			END) AS DATA_TYPE,
			UNNEST(PROARGMODES) AS IN_OUT,
			GENERATE_SERIES(1, SYS._ORA_ARGS_COUNT(OID)) AS POSITION
		FROM
			PG_PROC
	) AS SQ
		ON P.OID = SQ.OID
	/* Begin - ReqID:SRS-PLSQL-TYPE */
	LEFT JOIN 
	(
		SELECT
			OID,
			POSITION,
			TYPE_NAME,
			TYPE_SUBNAME,
			TYPE_OBJECT_TYPE,
			DATA_LENGTH,
			DATA_PRECISION,
			DATA_SCALE,
			PLS_TYPE
		FROM
	       pg_get_function_arg_reference_typerowtype()
	) AS ARG ON ARG.OID = SQ.OID AND ARG.POSITION = SQ.POSITION
	/* End - ReqID:SRS-PLSQL-TYPE */
	LEFT JOIN PG_TYPE AS T
		ON SQ.DATA_TYPE = T.OID
	LEFT JOIN PG_TRIGGER AS TR
		ON P.OID = TR.TGFOID
WHERE
	TR.OID IS NULL 
	AND P.PRONAMESPACE <> 'PG_CATALOG'::REGNAMESPACE::OID
	AND P.PRONAMESPACE <> 'PG_TOAST'::REGNAMESPACE::OID
	AND P.PRONAMESPACE <> 'INFORMATION_SCHEMA'::REGNAMESPACE::OID
ORDER BY
	OWNER, OBJECT_ID,OBJECT_NAME
;

/* Begin - ReqID:SRS-SQL-PACKAGE */
GRANT SELECT ON SYS.DBA_PROC_ARGUMENTS TO PUBLIC;

CREATE OR REPLACE VIEW SYS.DBA_PACKAGE_ARGUMENTS AS
SELECT
	SYS.ORA_CASE_TRANS(
		PG_GET_USERBYID(P.OWNER)::VARCHAR2
	)::VARCHAR2(128) AS OWNER,
	SYS.ORA_CASE_TRANS(P.PROC_NAME::VARCHAR2)::VARCHAR2(128) AS OBJECT_NAME,
	SYS.ORA_CASE_TRANS(P.PACKAGE_NAME::VARCHAR2)::VARCHAR2(128) AS PACKAGE_NAME,
	P.OID::VARCHAR2(10)::NUMBER AS OBJECT_ID,
	NULL::VARCHAR2(40) AS OVERLOAD,
	(P.FNO + 1)::NUMBER AS SUBPROGRAM_ID,
	CASE
	   WHEN SQ.ARGUMENT_NAME != '_NULL_' AND SQ.ARGUMENT_NAME != '_null_'
	        THEN SYS.ORA_CASE_TRANS(SQ.ARGUMENT_NAME::VARCHAR2)
	   ELSE
	        NULL
	END::VARCHAR2(128) AS ARGUMENT_NAME,
	SQ.POSITION::NUMBER AS POSITION,
	CASE
		WHEN P.KIND = 'f'
			THEN SQ.POSITION + 1
		ELSE SQ.POSITION
	END::NUMBER AS SEQUENCE,
	0::NUMBER AS DATA_LEVEL,
	CASE
	    /* Begin - ReqID:SRS-PLSQL-TYPE */
		WHEN SQ.TYPE_OBJECT_TYPE::VARCHAR2 = 'table' OR SQ.TYPE_OBJECT_TYPE::VARCHAR2 = 'TABLE'
		  OR SQ.TYPE_OBJECT_TYPE::VARCHAR2 = 'view' OR SQ.TYPE_OBJECT_TYPE::VARCHAR2 = 'VIEW'
		  THEN 'PL/SQL RECORD'
		/* End - ReqID:SRS-PLSQL-TYPE */
		WHEN SQ.DATA_TYPE = ANY(ARRAY['smallint', 'integer', 'bigint',
								   'numeric', 'number'])
			THEN 'NUMBER'
		WHEN SQ.DATA_TYPE = ANY(ARRAY['real', 'double precision'])
			THEN 'FLOAT'
		WHEN SQ.DATA_TYPE = 'bpchar'
			THEN 'CHAR'
		/* Begin - ReqID:SRS-PLSQL-RECORD */
		WHEN SQ.DATA_TYPE = 'orarecord'
		  THEN 'PL/SQL RECORD'
		/* End - ReqID:SRS-PLSQL-RECORD */
		ELSE ORA_CASE_TRANS(SQ.DATA_TYPE)::VARCHAR2(58)
	END::VARCHAR2(30) AS DATA_TYPE,
	CASE
		WHEN SQ.ARGDEFAULT = '_NULL_'
			THEN 'N'
		ELSE 'Y'
	END::VARCHAR2(1) AS DEFAULTED,
	NULL::LONG AS DEFAULT_VALUE,
	NULL::NUMBER AS DEFAULT_LENGTH,
	CASE
		WHEN SQ.IN_OUT = 'i' OR SQ.IN_OUT IS NULL
			THEN 'IN'
		WHEN SQ.IN_OUT = 'o'
			THEN 'OUT'
		WHEN SQ.IN_OUT = 'b'
			THEN 'IN/OUT'
		ELSE NULL
	END::VARCHAR2(9) AS IN_OUT,
	CASE
		/* Begin - ReqID:SRS-PLSQL-TYPE */
		WHEN SQ.DATA_LENGTH != 0
		    THEN SQ.DATA_LENGTH
		/* End - ReqID:SRS-PLSQL-TYPE */
		WHEN SQ.DATA_TYPE = ANY(ARRAY['smallint', 'integer', 'bigint',
								   'real', 'double precision',
								   'numeric', 'number'])
			THEN 22
		WHEN SQ.DATA_TYPE = ANY(ARRAY['long', 'long_raw'])
			THEN 32760
		ELSE NULL
	END::NUMBER AS DATA_LENGTH,
	CASE
		/* Begin - ReqID:SRS-PLSQL-TYPE */
		WHEN SQ.DATA_PRECISION != 0
		    THEN SQ.DATA_PRECISION
		/* End - ReqID:SRS-PLSQL-TYPE */
		WHEN SQ.DATA_TYPE = ANY(ARRAY['smallint', 'integer', 'bigint'])
			THEN 38
		WHEN SQ.DATA_TYPE = 'real'
			THEN 63
		WHEN SQ.DATA_TYPE = 'double precision'
			THEN 126
		WHEN SQ.DATA_TYPE = ANY(ARRAY['timestamp', 'timestamptz',
								   'oratimestamp', 'oratimestamptz',
								   'oratimestampltz'])
			THEN 6
		ELSE NULL
	END::NUMBER AS DATA_PRECISION,
	CASE
		/* Begin - ReqID:SRS-PLSQL-TYPE */
		WHEN SQ.DATA_SCALE != 0
		    THEN SQ.DATA_SCALE
		/* End - ReqID:SRS-PLSQL-TYPE */
		WHEN SQ.DATA_TYPE = ANY(ARRAY['real', 'double precision'])
			THEN -127
		ELSE NULL
	END::NUMBER AS DATA_SCALE,
	CASE
		WHEN SQ.DATA_TYPE= ANY(ARRAY['numeric', 'number',
								   'smallint', 'integer', 'bigint',
								   'real', 'double precision'])
			THEN 10
		ELSE NULL
	END::NUMBER AS RADIX,
	CASE
		WHEN SQ.DATA_TYPE::VARCHAR2(58) = ANY(ARRAY['char',
													  'character',
													  'varchar2',
													  'clob'])
			THEN 'CHAR_CS'
		WHEN SQ.DATA_TYPE::VARCHAR2(58) = ANY(ARRAY['nchar', 'nvarchar2',
													  'nclob'])
			THEN 'NCHAR_CS'
	END::VARCHAR2(44) AS CHARACTER_SET_NAME,
	NULL::VARCHAR2(128) AS TYPE_OWNER,
	/* Begin - ReqID:SRS-PLSQL-TYPE */
	CASE
		WHEN SQ.TYPE_NAME IS NOT NULL AND SQ.TYPE_NAME != '_NULL_' AND SQ.TYPE_NAME != '_null_'
		    THEN SYS.ORA_CASE_TRANS(SQ.TYPE_NAME)::VARCHAR2(128)
		ELSE NULL
	END::VARCHAR2(128) AS TYPE_NAME,
	/* End - ReqID:SRS-PLSQL-TYPE */
	NULL::VARCHAR2(128) AS TYPE_SUBNAME,
	NULL::VARCHAR2(128) AS TYPE_LINK,
	/* Begin - ReqID:SRS-PLSQL-TYPE */
	CASE
		WHEN SQ.TYPE_OBJECT_TYPE IS NOT NULL AND SQ.TYPE_OBJECT_TYPE != '_NULL_' AND SQ.TYPE_OBJECT_TYPE != '_null_'
		    THEN SYS.ORA_CASE_TRANS(SQ.TYPE_OBJECT_TYPE)::VARCHAR2(128)
		ELSE NULL
	END::VARCHAR2(128) AS TYPE_OBJECT_TYPE,
	CASE
		WHEN SQ.TYPE_OBJECT_TYPE = 'table' OR SQ.TYPE_OBJECT_TYPE = 'TABLE' OR SQ.TYPE_OBJECT_TYPE = 'view' OR SQ.TYPE_OBJECT_TYPE = 'VIEW'
			THEN 'ROWTYPE'
		ELSE NULL
	END::VARCHAR2(30) AS PLS_TYPE,
	/* End - ReqID:SRS-PLSQL-TYPE */
	CASE
		WHEN SQ.DATA_TYPE::VARCHAR2(58) = ANY(ARRAY['char',
													  'character',
													  'varchar2'])
			THEN NULL
		ELSE 0
	END::NUMBER AS CHAR_LENGTH,
	CASE
		WHEN SQ.DATA_TYPE::VARCHAR2(58) = ANY(ARRAY['char',
													  'character',
													  'varchar2'])
			THEN 'B'
		ELSE '0'
	END::VARCHAR2(1) AS CHAR_USED,
	0::VARCHAR2(256) AS ORIGIN_CON_ID
FROM
	PG_GET_SUBPROCS_IN_PACKAGE() AS P
	LEFT JOIN
	(
		SELECT
			OID,
			FNO,
			UNNEST(ARGNAMES) AS ARGUMENT_NAME,
			UNNEST(ARGTYPENAMES) AS DATA_TYPE,
			UNNEST(ARGMODES) AS IN_OUT,
			UNNEST(ARGDEFAULTS) AS ARGDEFAULT,
			GENERATE_SERIES(0, NARGS) AS POSITION,
			/* Begin - ReqID:SRS-PLSQL-TYPE */
			UNNEST(TYPE_NAMES) AS TYPE_NAME,
			UNNEST(TYPE_OBJECT_TYPES) AS TYPE_OBJECT_TYPE,
			UNNEST(DATA_LENGTHS) AS DATA_LENGTH,
			UNNEST(DATA_PRECISIONS) AS DATA_PRECISION,
			UNNEST(DATA_SCALES) AS DATA_SCALE
			/* End - ReqID:SRS-PLSQL-TYPE */
		FROM
			PG_GET_SUBPROCS_IN_PACKAGE() WHERE KIND = 'f'
		UNION ALL
		SELECT
			OID,
			FNO,
			UNNEST(ARGNAMES) AS ARGUMENT_NAME,
			UNNEST(ARGTYPENAMES) AS DATA_TYPE,
			UNNEST(ARGMODES) AS IN_OUT,
			UNNEST(ARGDEFAULTS) AS ARGDEFAULT,
			GENERATE_SERIES(1, NARGS) AS POSITION,
			/* Begin - ReqID:SRS-PLSQL-TYPE */
			UNNEST(TYPE_NAMES) AS TYPE_NAME,
			UNNEST(TYPE_OBJECT_TYPES) AS TYPE_OBJECT_TYPE,
			UNNEST(DATA_LENGTHS) AS DATA_LENGTH,
			UNNEST(DATA_PRECISIONS) AS DATA_PRECISION,
			UNNEST(DATA_SCALES) AS DATA_SCALE
			/* End - ReqID:SRS-PLSQL-TYPE */
		FROM
			PG_GET_SUBPROCS_IN_PACKAGE() WHERE NARGS > 0 AND KIND = 'p'
	) AS SQ
		ON P.OID = SQ.OID AND P.FNO = SQ.FNO
WHERE
    SQ.POSITION IS NOT NULL
	AND P.NAMESPACE <> 'PG_CATALOG'::REGNAMESPACE::OID
	AND P.NAMESPACE <> 'PG_TOAST'::REGNAMESPACE::OID
	AND P.NAMESPACE <> 'INFORMATION_SCHEMA'::REGNAMESPACE::OID
ORDER BY
	OWNER, OBJECT_ID,OBJECT_NAME
;

GRANT SELECT ON SYS.DBA_PACKAGE_ARGUMENTS TO PUBLIC;

CREATE OR REPLACE VIEW SYS.DBA_ARGUMENTS AS
	SELECT * FROM SYS.DBA_PROC_ARGUMENTS --come from pg_proc
UNION ALL
	SELECT * FROM SYS.DBA_PACKAGE_ARGUMENTS --come from pg_package
ORDER BY
	OWNER, OBJECT_ID,OBJECT_NAME
;
/* End - ReqID:SRS-SQL-PACKAGE */

/* GRANT SELECT PRIVILEGE TO PUBLIC */
GRANT SELECT ON SYS.DBA_ARGUMENTS TO PUBLIC;

/* ALL_ARGUMENTS */
CREATE OR REPLACE VIEW SYS.ALL_PROC_ARGUMENTS AS
SELECT
	SYS.ORA_CASE_TRANS(
		PG_GET_USERBYID(P.PROOWNER)::VARCHAR2
	)::VARCHAR2(128) AS OWNER,
	SYS.ORA_CASE_TRANS(P.PRONAME::VARCHAR2)::VARCHAR2(128) AS OBJECT_NAME,
	NULL::VARCHAR2(128) AS PACKAGE_NAME,
	P.OID::VARCHAR2(10)::NUMBER AS OBJECT_ID,
	NULL::VARCHAR2(40) AS OVERLOAD,
	1::NUMBER AS SUBPROGRAM_ID,
	SYS.ORA_CASE_TRANS(
		SQ.ARGUMENT_NAME::VARCHAR2
	)::VARCHAR2(128) AS ARGUMENT_NAME,
	SQ.POSITION::NUMBER AS POSITION,
	CASE
		WHEN P.PROKIND = 'f'
			THEN SQ.POSITION + 1
		ELSE SQ.POSITION
	END::NUMBER AS SEQUENCE,
	0::NUMBER AS DATA_LEVEL,
	CASE
	    /* Begin - ReqID:SRS-PLSQL-TYPE */
		WHEN ARG.TYPE_OBJECT_TYPE::VARCHAR2 = 'table' OR ARG.TYPE_OBJECT_TYPE::VARCHAR2 = 'TABLE'
		  OR ARG.TYPE_OBJECT_TYPE::VARCHAR2 = 'view' OR ARG.TYPE_OBJECT_TYPE::VARCHAR2 = 'VIEW'
		  THEN 'PL/SQL RECORD'
		/* End - ReqID:SRS-PLSQL-TYPE */
		WHEN T.TYPNAME = ANY(ARRAY['int2', 'int4', 'int8',
								   'numeric', 'number'])
			THEN 'NUMBER'
		WHEN T.TYPNAME = ANY(ARRAY['float4', 'float8'])
			THEN 'FLOAT'
		WHEN T.TYPNAME = 'bpchar'
			THEN 'CHAR'
		/* Begin - ReqID:SRS-PLSQL-RECORD */
		WHEN T.TYPNAME = 'orarecord'
		  THEN 'PL/SQL RECORD'
		/* End - ReqID:SRS-PLSQL-RECORD */
		ELSE ORA_CASE_TRANS(T.OID::REGTYPE::VARCHAR2)::VARCHAR2(58)
	END::VARCHAR2(30) AS DATA_TYPE,
	/* Begin - BUG#Z170 */
	CASE
		WHEN PG_GET_FUNCTION_ARG_DEFAULT(SQ.OID, SQ.POSITION) IS NULL
			THEN 'N'
		ELSE 'Y'
	END::VARCHAR2(1) AS DEFAULTED,
	/* End - BUG#Z170 */
	NULL::LONG AS DEFAULT_VALUE,
	NULL::NUMBER AS DEFAULT_LENGTH,
	CASE
		WHEN SQ.IN_OUT = 'i' OR SQ.IN_OUT IS NULL
			THEN 'IN'
		WHEN SQ.IN_OUT = 'o'
			THEN 'OUT'
		WHEN SQ.IN_OUT = 'b'
			THEN 'IN/OUT'
		ELSE NULL
	END::VARCHAR2(9) AS IN_OUT,
	CASE
		/* Begin - ReqID:SRS-PLSQL-TYPE */
		WHEN ARG.DATA_LENGTH IS NOT NULL
		    THEN ARG.DATA_LENGTH
		/* End - ReqID:SRS-PLSQL-TYPE */
		WHEN T.TYPNAME = ANY(ARRAY['int2', 'int4', 'int8',
								   'float4', 'float8',
								   'numeric', 'number'])
			THEN 22
		WHEN T.TYPNAME = ANY(ARRAY['long', 'long_raw'])
			THEN 32760
		ELSE NULL
	END::NUMBER AS DATA_LENGTH,
	CASE
		/* Begin - ReqID:SRS-PLSQL-TYPE */
		WHEN ARG.DATA_PRECISION IS NOT NULL
		    THEN ARG.DATA_PRECISION
		/* End - ReqID:SRS-PLSQL-TYPE */
		WHEN T.TYPNAME = ANY(ARRAY['int2', 'int4', 'int8'])
			THEN 38
		WHEN T.TYPNAME = 'float4'
			THEN 63
		WHEN T.TYPNAME = 'float8'
			THEN 126
		WHEN T.TYPNAME = ANY(ARRAY['timestamp', 'timestamptz',
								   'oratimestamp', 'oratimestamptz',
								   'oratimestampltz'])
			THEN 6
		ELSE NULL
	END::NUMBER AS DATA_PRECISION,
	CASE
		/* Begin - ReqID:SRS-PLSQL-TYPE */
		WHEN ARG.DATA_SCALE IS NOT NULL
		    THEN ARG.DATA_SCALE
		/* End - ReqID:SRS-PLSQL-TYPE */
		WHEN T.TYPNAME = ANY(ARRAY['float4', 'float8'])
			THEN -127
		ELSE NULL
	END::NUMBER AS DATA_SCALE,
	CASE
		WHEN T.TYPNAME = ANY(ARRAY['numeric', 'number',
								   'int2', 'int4', 'int8',
								   'float4', 'float8'])
			THEN 10
		ELSE NULL
	END::NUMBER AS RADIX,
	CASE
		WHEN T.OID::REGTYPE::VARCHAR2(58) = ANY(ARRAY['char',
													  'character',
													  'varchar2',
													  'clob'])
			THEN 'CHAR_CS'
		WHEN T.OID::REGTYPE::VARCHAR2(58) = ANY(ARRAY['nchar', 'nvarchar2',
													  'nclob'])
			THEN 'NCHAR_CS'
	END::VARCHAR2(44) AS CHARACTER_SET_NAME,
	NULL::VARCHAR2(128) AS TYPE_OWNER,
	/* Begin - ReqID:SRS-PLSQL-TYPE */
	CASE
	   WHEN ARG.TYPE_NAME != '_NULL_'
	        THEN SYS.ORA_CASE_TRANS(ARG.TYPE_NAME::VARCHAR2)::VARCHAR2(128)
	   ELSE
	        NULL
	END::VARCHAR2(128) AS TYPE_NAME,
	CASE
	   WHEN ARG.TYPE_SUBNAME != '_NULL_'
	        THEN SYS.ORA_CASE_TRANS(ARG.TYPE_SUBNAME::VARCHAR2)::VARCHAR2(128)
	   ELSE
	        NULL
	END::VARCHAR2(128) AS TYPE_SUBNAME,
	/* End - ReqID:SRS-PLSQL-TYPE */
	NULL::VARCHAR2(128) AS TYPE_LINK,
	/* Begin - ReqID:SRS-PLSQL-TYPE */
	CASE
	   WHEN ARG.TYPE_OBJECT_TYPE != '_NULL_'
	        THEN SYS.ORA_CASE_TRANS(ARG.TYPE_OBJECT_TYPE::VARCHAR2)::VARCHAR2(128)
	   ELSE
	        NULL
	END::VARCHAR2(128) AS TYPE_OBJECT_TYPE,
    /* End - ReqID:SRS-PLSQL-TYPE */
	CASE
		WHEN (T.TYPTYPE = 'b' OR T.TYPTYPE = 'c') AND ARG.PLS_TYPE IS NOT NULL
			THEN SYS.ORA_CASE_TRANS(ARG.PLS_TYPE)
		WHEN T.TYPTYPE = 'b' AND ARG.PLS_TYPE IS NULL
			THEN SYS.ORA_CASE_TRANS(T.OID::REGTYPE::VARCHAR2)
		WHEN T.TYPTYPE = 'd' AND T.TYPNAME = 'raw'
			THEN 'RAW'
		WHEN T.TYPTYPE = 'd' AND T.TYPNAME = 'blob'
			THEN 'BLOB'
		WHEN T.TYPTYPE = 'd' AND T.TYPNAME = 'clob'
			THEN 'CLOB'
		WHEN T.TYPTYPE = 'd' AND T.TYPNAME = 'nclob'
			THEN 'CLOB'
		WHEN T.TYPTYPE = 'd' AND T.TYPNAME = 'long'
			THEN 'LONG'
		WHEN T.TYPTYPE = 'd' AND T.TYPNAME = 'long_raw'
			THEN 'LONG_RAW'
		ELSE NULL
	END::VARCHAR2(30) AS PLS_TYPE,
	CASE
		WHEN T.OID::REGTYPE::VARCHAR2(58) = ANY(ARRAY['char',
													  'character',
													  'varchar2'])
			THEN NULL
		ELSE 0
	END::NUMBER AS CHAR_LENGTH,
	CASE
		WHEN T.OID::REGTYPE::VARCHAR2(58) = ANY(ARRAY['char',
													  'character',
													  'varchar2'])
			THEN 'B'
		ELSE '0'
	END::VARCHAR2(1) AS CHAR_USED,
	0::VARCHAR2(256) AS ORIGIN_CON_ID
FROM
	PG_PROC AS P
	LEFT JOIN
	(
		SELECT
			OID,
			NULL AS ARGUMENT_NAME,
			PRORETTYPE AS DATA_TYPE,
			'o' AS IN_OUT,
			0 AS POSITION
		FROM
			PG_PROC
		WHERE
			PROKIND = 'f'
		UNION ALL
		SELECT
			OID,
			UNNEST(PROARGNAMES) AS ARGUMENT_NAME,
			UNNEST(
			CASE
				WHEN PROALLARGTYPES IS NOT NULL
					THEN PROALLARGTYPES
				ELSE PROARGTYPES
			END) AS DATA_TYPE,
			UNNEST(PROARGMODES) AS IN_OUT,
			GENERATE_SERIES(1, SYS._ORA_ARGS_COUNT(OID)) AS POSITION
		FROM
			PG_PROC
	) AS SQ
		ON P.OID = SQ.OID
	/* Begin - ReqID:SRS-PLSQL-TYPE */
	LEFT JOIN
	(
		SELECT
			OID,
			POSITION,
			TYPE_NAME,
			TYPE_SUBNAME,
			TYPE_OBJECT_TYPE,
			DATA_LENGTH,
			DATA_PRECISION,
			DATA_SCALE,
			PLS_TYPE
		FROM
	       pg_get_function_arg_reference_typerowtype()
	) AS ARG ON ARG.OID = SQ.OID AND ARG.POSITION = SQ.POSITION
	/* End - ReqID:SRS-PLSQL-TYPE */
	LEFT JOIN PG_TYPE AS T
		ON SQ.DATA_TYPE = T.OID
	LEFT JOIN PG_TRIGGER AS TR
		ON P.OID = TR.TGFOID
WHERE
	TR.OID IS NULL 
	AND P.PRONAMESPACE <> 'PG_CATALOG'::REGNAMESPACE::OID
	AND P.PRONAMESPACE <> 'PG_TOAST'::REGNAMESPACE::OID
	AND P.PRONAMESPACE <> 'INFORMATION_SCHEMA'::REGNAMESPACE::OID
	AND HAS_SCHEMA_PRIVILEGE(P.PRONAMESPACE, 'USAGE')	/* BUG#Z169 */
	AND HAS_FUNCTION_PRIVILEGE(P.OID, 'EXECUTE')
ORDER BY
	OWNER, OBJECT_ID
;

/* Begin - ReqID:SRS-SQL-PACKAGE */
GRANT SELECT ON SYS.ALL_PROC_ARGUMENTS TO PUBLIC;

CREATE OR REPLACE VIEW SYS.ALL_PACKAGE_ARGUMENTS AS
SELECT
	SYS.ORA_CASE_TRANS(
		PG_GET_USERBYID(P.OWNER)::VARCHAR2
	)::VARCHAR2(128) AS OWNER,
	SYS.ORA_CASE_TRANS(P.PROC_NAME::VARCHAR2)::VARCHAR2(128) AS OBJECT_NAME,
	SYS.ORA_CASE_TRANS(P.PACKAGE_NAME::VARCHAR2)::VARCHAR2(128) AS PACKAGE_NAME,
	P.OID::VARCHAR2(10)::NUMBER AS OBJECT_ID,
	NULL::VARCHAR2(40) AS OVERLOAD,
	(P.FNO + 1)::NUMBER AS SUBPROGRAM_ID,
	CASE
	   WHEN SQ.ARGUMENT_NAME != '_NULL_' AND SQ.ARGUMENT_NAME != '_null_'
	        THEN SYS.ORA_CASE_TRANS(SQ.ARGUMENT_NAME::VARCHAR2)
	   ELSE
	        NULL
	END::VARCHAR2(128) AS ARGUMENT_NAME,
	SQ.POSITION::NUMBER AS POSITION,
	CASE
		WHEN P.KIND = 'f'
			THEN SQ.POSITION + 1
		ELSE SQ.POSITION
	END::NUMBER AS SEQUENCE,
	0::NUMBER AS DATA_LEVEL,
	CASE
	    /* Begin - ReqID:SRS-PLSQL-TYPE */
		WHEN SQ.TYPE_OBJECT_TYPE::VARCHAR2 = 'table' OR SQ.TYPE_OBJECT_TYPE::VARCHAR2 = 'TABLE'
		  OR SQ.TYPE_OBJECT_TYPE::VARCHAR2 = 'view' OR SQ.TYPE_OBJECT_TYPE::VARCHAR2 = 'VIEW'
		  THEN 'PL/SQL RECORD'
		/* End - ReqID:SRS-PLSQL-TYPE */
		WHEN SQ.DATA_TYPE = ANY(ARRAY['smallint', 'integer', 'bigint',
								   'numeric', 'number'])
			THEN 'NUMBER'
		WHEN SQ.DATA_TYPE = ANY(ARRAY['real', 'double precision'])
			THEN 'FLOAT'
		WHEN SQ.DATA_TYPE = 'bpchar'
			THEN 'CHAR'
		/* Begin - ReqID:SRS-PLSQL-RECORD */
		WHEN SQ.DATA_TYPE = 'orarecord'
		  THEN 'PL/SQL RECORD'
		/* End - ReqID:SRS-PLSQL-RECORD */
		ELSE ORA_CASE_TRANS(SQ.DATA_TYPE)::VARCHAR2(58)
	END::VARCHAR2(30) AS DATA_TYPE,
	CASE
		WHEN SQ.ARGDEFAULT = '_NULL_'
			THEN 'N'
		ELSE 'Y'
	END::VARCHAR2(1) AS DEFAULTED,
	NULL::LONG AS DEFAULT_VALUE,
	NULL::NUMBER AS DEFAULT_LENGTH,
	CASE
		WHEN SQ.IN_OUT = 'i' OR SQ.IN_OUT IS NULL
			THEN 'IN'
		WHEN SQ.IN_OUT = 'o'
			THEN 'OUT'
		WHEN SQ.IN_OUT = 'b'
			THEN 'IN/OUT'
		ELSE NULL
	END::VARCHAR2(9) AS IN_OUT,
	CASE
		/* Begin - ReqID:SRS-PLSQL-TYPE */
		WHEN SQ.DATA_LENGTH != 0
		    THEN SQ.DATA_LENGTH
		/* End - ReqID:SRS-PLSQL-TYPE */
		WHEN SQ.DATA_TYPE = ANY(ARRAY['smallint', 'integer', 'bigint',
								   'real', 'double precision',
								   'numeric', 'number'])
			THEN 22
		WHEN SQ.DATA_TYPE = ANY(ARRAY['long', 'long_raw'])
			THEN 32760
		ELSE NULL
	END::NUMBER AS DATA_LENGTH,
	CASE
		/* Begin - ReqID:SRS-PLSQL-TYPE */
		WHEN SQ.DATA_PRECISION != 0
		    THEN SQ.DATA_PRECISION
		/* End - ReqID:SRS-PLSQL-TYPE */
		WHEN SQ.DATA_TYPE = ANY(ARRAY['smallint', 'integer', 'bigint'])
			THEN 38
		WHEN SQ.DATA_TYPE = 'real'
			THEN 63
		WHEN SQ.DATA_TYPE = 'double precision'
			THEN 126
		WHEN SQ.DATA_TYPE = ANY(ARRAY['timestamp', 'timestamptz',
								   'oratimestamp', 'oratimestamptz',
								   'oratimestampltz'])
			THEN 6
		ELSE NULL
	END::NUMBER AS DATA_PRECISION,
	CASE
		/* Begin - ReqID:SRS-PLSQL-TYPE */
		WHEN SQ.DATA_SCALE != 0
		    THEN SQ.DATA_SCALE
		/* End - ReqID:SRS-PLSQL-TYPE */
		WHEN SQ.DATA_TYPE = ANY(ARRAY['real', 'double precision'])
			THEN -127
		ELSE NULL
	END::NUMBER AS DATA_SCALE,
	CASE
		WHEN SQ.DATA_TYPE= ANY(ARRAY['numeric', 'number',
								   'smallint', 'integer', 'bigint',
								   'real', 'double precision'])
			THEN 10
		ELSE NULL
	END::NUMBER AS RADIX,
	CASE
		WHEN SQ.DATA_TYPE::VARCHAR2(58) = ANY(ARRAY['char',
													  'character',
													  'varchar2',
													  'clob'])
			THEN 'CHAR_CS'
		WHEN SQ.DATA_TYPE::VARCHAR2(58) = ANY(ARRAY['nchar', 'nvarchar2',
													  'nclob'])
			THEN 'NCHAR_CS'
	END::VARCHAR2(44) AS CHARACTER_SET_NAME,
	NULL::VARCHAR2(128) AS TYPE_OWNER,
	/* Begin - ReqID:SRS-PLSQL-TYPE */
	CASE
		WHEN SQ.TYPE_NAME IS NOT NULL AND SQ.TYPE_NAME != '_NULL_' AND SQ.TYPE_NAME != '_null_'
		    THEN SYS.ORA_CASE_TRANS(SQ.TYPE_NAME)::VARCHAR2(128)
		ELSE NULL
	END::VARCHAR2(128) AS TYPE_NAME,
	/* End - ReqID:SRS-PLSQL-TYPE */
	NULL::VARCHAR2(128) AS TYPE_SUBNAME,
	NULL::VARCHAR2(128) AS TYPE_LINK,
	/* Begin - ReqID:SRS-PLSQL-TYPE */
	CASE
		WHEN SQ.TYPE_OBJECT_TYPE IS NOT NULL AND SQ.TYPE_OBJECT_TYPE != '_NULL_' AND SQ.TYPE_OBJECT_TYPE != '_null_'
		    THEN SYS.ORA_CASE_TRANS(SQ.TYPE_OBJECT_TYPE)::VARCHAR2(128)
		ELSE NULL
	END::VARCHAR2(128) AS TYPE_OBJECT_TYPE,
	CASE
		WHEN SQ.TYPE_OBJECT_TYPE = 'table' OR SQ.TYPE_OBJECT_TYPE = 'TABLE' OR SQ.TYPE_OBJECT_TYPE = 'view' OR SQ.TYPE_OBJECT_TYPE = 'VIEW'
			THEN 'ROWTYPE'
		ELSE NULL
	END::VARCHAR2(30) AS PLS_TYPE,
	/* End - ReqID:SRS-PLSQL-TYPE */
	CASE
		WHEN SQ.DATA_TYPE::VARCHAR2(58) = ANY(ARRAY['char',
													  'character',
													  'varchar2'])
			THEN NULL
		ELSE 0
	END::NUMBER AS CHAR_LENGTH,
	CASE
		WHEN SQ.DATA_TYPE::VARCHAR2(58) = ANY(ARRAY['char',
													  'character',
													  'varchar2'])
			THEN 'B'
		ELSE '0'
	END::VARCHAR2(1) AS CHAR_USED,
	0::VARCHAR2(256) AS ORIGIN_CON_ID
FROM
	PG_GET_SUBPROCS_IN_PACKAGE() AS P
	LEFT JOIN
	(
		SELECT
			OID,
			FNO,
			UNNEST(ARGNAMES) AS ARGUMENT_NAME,
			UNNEST(ARGTYPENAMES) AS DATA_TYPE,
			UNNEST(ARGMODES) AS IN_OUT,
			UNNEST(ARGDEFAULTS) AS ARGDEFAULT,
			GENERATE_SERIES(0, NARGS) AS POSITION,
			/* Begin - ReqID:SRS-PLSQL-TYPE */
			UNNEST(TYPE_NAMES) AS TYPE_NAME,
			UNNEST(TYPE_OBJECT_TYPES) AS TYPE_OBJECT_TYPE,
			UNNEST(DATA_LENGTHS) AS DATA_LENGTH,
			UNNEST(DATA_PRECISIONS) AS DATA_PRECISION,
			UNNEST(DATA_SCALES) AS DATA_SCALE
			/* End - ReqID:SRS-PLSQL-TYPE */
		FROM
			PG_GET_SUBPROCS_IN_PACKAGE() WHERE KIND = 'f'
		UNION ALL
		SELECT
			OID,
			FNO,
			UNNEST(ARGNAMES) AS ARGUMENT_NAME,
			UNNEST(ARGTYPENAMES) AS DATA_TYPE,
			UNNEST(ARGMODES) AS IN_OUT,
			UNNEST(ARGDEFAULTS) AS ARGDEFAULT,
			GENERATE_SERIES(1, NARGS) AS POSITION,
			/* Begin - ReqID:SRS-PLSQL-TYPE */
			UNNEST(TYPE_NAMES) AS TYPE_NAME,
			UNNEST(TYPE_OBJECT_TYPES) AS TYPE_OBJECT_TYPE,
			UNNEST(DATA_LENGTHS) AS DATA_LENGTH,
			UNNEST(DATA_PRECISIONS) AS DATA_PRECISION,
			UNNEST(DATA_SCALES) AS DATA_SCALE
			/* End - ReqID:SRS-PLSQL-TYPE */
		FROM
			PG_GET_SUBPROCS_IN_PACKAGE() WHERE NARGS > 0 AND KIND = 'p'
	) AS SQ
		ON P.OID = SQ.OID AND P.FNO = SQ.FNO
WHERE
    SQ.POSITION IS NOT NULL
	AND P.NAMESPACE <> 'PG_CATALOG'::REGNAMESPACE::OID
	AND P.NAMESPACE <> 'PG_TOAST'::REGNAMESPACE::OID
	AND P.NAMESPACE <> 'INFORMATION_SCHEMA'::REGNAMESPACE::OID
	AND HAS_SCHEMA_PRIVILEGE(P.NAMESPACE, 'USAGE')	/* BUG#Z169 */
	AND HAS_PACKAGE_PRIVILEGE(P.OID, 'EXECUTE')
ORDER BY
	OWNER, OBJECT_ID,OBJECT_NAME
;

GRANT SELECT ON SYS.ALL_PACKAGE_ARGUMENTS TO PUBLIC;

CREATE OR REPLACE VIEW SYS.ALL_ARGUMENTS AS
	SELECT * FROM SYS.ALL_PROC_ARGUMENTS --come from pg_proc
UNION ALL
	SELECT * FROM SYS.ALL_PACKAGE_ARGUMENTS --come from pg_package
ORDER BY
	OWNER, OBJECT_ID,OBJECT_NAME
;
/* End - ReqID:SRS-SQL-PACKAGE */

/* GRANT SELECT PRIVILEGE TO PUBLIC */
GRANT SELECT ON SYS.ALL_ARGUMENTS TO PUBLIC;

/* USER_ARGUMENTS */
CREATE OR REPLACE VIEW SYS.USER_PROC_ARGUMENTS AS
SELECT
	SYS.ORA_CASE_TRANS(P.PRONAME::VARCHAR2)::VARCHAR2(128) AS OBJECT_NAME,
	NULL::VARCHAR2(128) AS PACKAGE_NAME,
	P.OID::VARCHAR2(10)::NUMBER AS OBJECT_ID,
	NULL::VARCHAR2(40) AS OVERLOAD,
	1::NUMBER AS SUBPROGRAM_ID,
	SYS.ORA_CASE_TRANS(
		SQ.ARGUMENT_NAME::VARCHAR2
	)::VARCHAR2(128) AS ARGUMENT_NAME,
	SQ.POSITION::NUMBER AS POSITION,
	CASE
		WHEN P.PROKIND = 'f'
			THEN SQ.POSITION + 1
		ELSE SQ.POSITION
	END::NUMBER AS SEQUENCE,
	0::NUMBER AS DATA_LEVEL,
	CASE
	    /* Begin - ReqID:SRS-PLSQL-TYPE */
		WHEN ARG.TYPE_OBJECT_TYPE::VARCHAR2 = 'table' OR ARG.TYPE_OBJECT_TYPE::VARCHAR2 = 'TABLE'
		  OR ARG.TYPE_OBJECT_TYPE::VARCHAR2 = 'view' OR ARG.TYPE_OBJECT_TYPE::VARCHAR2 = 'VIEW'
		  THEN 'PL/SQL RECORD'
		/* End - ReqID:SRS-PLSQL-TYPE */
		WHEN T.TYPNAME = ANY(ARRAY['int2', 'int4', 'int8',
								   'numeric', 'number'])
			THEN 'NUMBER'
		WHEN T.TYPNAME = ANY(ARRAY['float4', 'float8'])
			THEN 'FLOAT'
		WHEN T.TYPNAME = 'bpchar'
			THEN 'CHAR'
		/* Begin - ReqID:SRS-PLSQL-RECORD */
		WHEN T.TYPNAME = 'orarecord'
		  THEN 'PL/SQL RECORD'
		/* End - ReqID:SRS-PLSQL-RECORD */
		ELSE ORA_CASE_TRANS(T.OID::REGTYPE::VARCHAR2)::VARCHAR2(58)
	END::VARCHAR2(30) AS DATA_TYPE,
	/* Begin - BUG#Z170 */
	CASE
		WHEN PG_GET_FUNCTION_ARG_DEFAULT(SQ.OID, SQ.POSITION) IS NULL
			THEN 'N'
		ELSE 'Y'
	END::VARCHAR2(1) AS DEFAULTED,
	/* End - BUG#Z170 */
	NULL::LONG AS DEFAULT_VALUE,
	NULL::NUMBER AS DEFAULT_LENGTH,
	CASE
		WHEN SQ.IN_OUT = 'i' OR SQ.IN_OUT IS NULL
			THEN 'IN'
		WHEN SQ.IN_OUT = 'o'
			THEN 'OUT'
		WHEN SQ.IN_OUT = 'b'
			THEN 'IN/OUT'
		ELSE NULL
	END::VARCHAR2(9) AS IN_OUT,
	CASE
		/* Begin - ReqID:SRS-PLSQL-TYPE */
		WHEN ARG.DATA_LENGTH IS NOT NULL
		    THEN ARG.DATA_LENGTH
		/* End - ReqID:SRS-PLSQL-TYPE */
		WHEN T.TYPNAME = ANY(ARRAY['int2', 'int4', 'int8',
								   'float4', 'float8',
								   'numeric', 'number'])
			THEN 22
		WHEN T.TYPNAME = ANY(ARRAY['long', 'long_raw'])
			THEN 32760
		ELSE NULL
	END::NUMBER AS DATA_LENGTH,
	CASE
		/* Begin - ReqID:SRS-PLSQL-TYPE */
		WHEN ARG.DATA_PRECISION IS NOT NULL
		    THEN ARG.DATA_PRECISION
		/* End - ReqID:SRS-PLSQL-TYPE */
		WHEN T.TYPNAME = ANY(ARRAY['int2', 'int4', 'int8'])
			THEN 38
		WHEN T.TYPNAME = 'float4'
			THEN 63
		WHEN T.TYPNAME = 'float8'
			THEN 126
		WHEN T.TYPNAME = ANY(ARRAY['timestamp', 'timestamptz',
								   'oratimestamp', 'oratimestamptz',
								   'oratimestampltz'])
			THEN 6
		ELSE NULL
	END::NUMBER AS DATA_PRECISION,
	CASE
		/* Begin - ReqID:SRS-PLSQL-TYPE */
		WHEN ARG.DATA_SCALE IS NOT NULL
		    THEN ARG.DATA_SCALE
		/* End - ReqID:SRS-PLSQL-TYPE */
		WHEN T.TYPNAME = ANY(ARRAY['float4', 'float8'])
			THEN -127
		ELSE NULL
	END::NUMBER AS DATA_SCALE,
	CASE
		WHEN T.TYPNAME = ANY(ARRAY['numeric', 'number',
								   'int2', 'int4', 'int8',
								   'float4', 'float8'])
			THEN 10
		ELSE NULL
	END::NUMBER AS RADIX,
	CASE
		WHEN T.OID::REGTYPE::VARCHAR2(58) = ANY(ARRAY['char',
													  'character',
													  'varchar2',
													  'clob'])
			THEN 'CHAR_CS'
		WHEN T.OID::REGTYPE::VARCHAR2(58) = ANY(ARRAY['nchar', 'nvarchar2',
													  'nclob'])
			THEN 'NCHAR_CS'
	END::VARCHAR2(44) AS CHARACTER_SET_NAME,
	NULL::VARCHAR2(128) AS TYPE_OWNER,
	/* Begin - ReqID:SRS-PLSQL-TYPE */
	CASE
	   WHEN ARG.TYPE_NAME != '_NULL_'
	        THEN SYS.ORA_CASE_TRANS(ARG.TYPE_NAME::VARCHAR2)::VARCHAR2(128)
	   ELSE
	        NULL
	END::VARCHAR2(128) AS TYPE_NAME,
	CASE
	   WHEN ARG.TYPE_SUBNAME != '_NULL_'
	        THEN SYS.ORA_CASE_TRANS(ARG.TYPE_SUBNAME::VARCHAR2)::VARCHAR2(128)
	   ELSE
	        NULL
	END::VARCHAR2(128) AS TYPE_SUBNAME,
	/* End - ReqID:SRS-PLSQL-TYPE */
	NULL::VARCHAR2(128) AS TYPE_LINK,
	/* Begin - ReqID:SRS-PLSQL-TYPE */
	CASE
	   WHEN ARG.TYPE_OBJECT_TYPE != '_NULL_'
	        THEN SYS.ORA_CASE_TRANS(ARG.TYPE_OBJECT_TYPE::VARCHAR2)::VARCHAR2(128)
	   ELSE
	        NULL
	END::VARCHAR2(128) AS TYPE_OBJECT_TYPE,
    /* End - ReqID:SRS-PLSQL-TYPE */
	CASE
		WHEN (T.TYPTYPE = 'b' OR T.TYPTYPE = 'c') AND ARG.PLS_TYPE IS NOT NULL
			THEN SYS.ORA_CASE_TRANS(ARG.PLS_TYPE)
		WHEN T.TYPTYPE = 'b' AND ARG.PLS_TYPE IS NULL
			THEN SYS.ORA_CASE_TRANS(T.OID::REGTYPE::VARCHAR2)
		WHEN T.TYPTYPE = 'd' AND T.TYPNAME = 'raw'
			THEN 'RAW'
		WHEN T.TYPTYPE = 'd' AND T.TYPNAME = 'blob'
			THEN 'BLOB'
		WHEN T.TYPTYPE = 'd' AND T.TYPNAME = 'clob'
			THEN 'CLOB'
		WHEN T.TYPTYPE = 'd' AND T.TYPNAME = 'nclob'
			THEN 'CLOB'
		WHEN T.TYPTYPE = 'd' AND T.TYPNAME = 'long'
			THEN 'LONG'
		WHEN T.TYPTYPE = 'd' AND T.TYPNAME = 'long_raw'
			THEN 'LONG_RAW'
		ELSE NULL
	END::VARCHAR2(30) AS PLS_TYPE,
	CASE
		WHEN T.OID::REGTYPE::VARCHAR2(58) = ANY(ARRAY['char',
													  'character',
													  'varchar2'])
			THEN NULL
		ELSE 0
	END::NUMBER AS CHAR_LENGTH,
	CASE
		WHEN T.OID::REGTYPE::VARCHAR2(58) = ANY(ARRAY['char',
													  'character',
													  'varchar2'])
			THEN 'B'
		ELSE '0'
	END::VARCHAR2(1) AS CHAR_USED,
	0::VARCHAR2(256) AS ORIGIN_CON_ID
FROM
	PG_PROC AS P
	LEFT JOIN
	(
		SELECT
			OID,
			NULL AS ARGUMENT_NAME,
			PRORETTYPE AS DATA_TYPE,
			'o' AS IN_OUT,
			0 AS POSITION
		FROM
			PG_PROC
		WHERE
			PROKIND = 'f'
		UNION ALL
		SELECT
			OID,
			UNNEST(PROARGNAMES) AS ARGUMENT_NAME,
			UNNEST(
			CASE
				WHEN PROALLARGTYPES IS NOT NULL
					THEN PROALLARGTYPES
				ELSE PROARGTYPES
			END) AS DATA_TYPE,
			UNNEST(PROARGMODES) AS IN_OUT,
			GENERATE_SERIES(1, SYS._ORA_ARGS_COUNT(OID)) AS POSITION
		FROM
			PG_PROC
	) AS SQ
		ON P.OID = SQ.OID
	/* Begin - ReqID:SRS-PLSQL-TYPE */
	LEFT JOIN
	(
		SELECT
			OID,
			POSITION,
			TYPE_NAME,
			TYPE_SUBNAME,
			TYPE_OBJECT_TYPE,
			DATA_LENGTH,
			DATA_PRECISION,
			DATA_SCALE,
			PLS_TYPE
		FROM
	       pg_get_function_arg_reference_typerowtype()
	) AS ARG ON ARG.OID = SQ.OID AND ARG.POSITION = SQ.POSITION
	/* End - ReqID:SRS-PLSQL-TYPE */
	LEFT JOIN PG_TYPE AS T
		ON SQ.DATA_TYPE = T.OID
	LEFT JOIN PG_TRIGGER AS TR
		ON P.OID = TR.TGFOID
WHERE
	TR.OID IS NULL 
	AND P.PRONAMESPACE <> 'PG_CATALOG'::REGNAMESPACE::OID
	AND P.PRONAMESPACE <> 'PG_TOAST'::REGNAMESPACE::OID
	AND P.PRONAMESPACE <> 'INFORMATION_SCHEMA'::REGNAMESPACE::OID
	AND PG_GET_USERBYID(P.PROOWNER) = CURRENT_USER	/* BUG#M0000074 */
ORDER BY
	OBJECT_ID
;

/* Begin - ReqID:SRS-SQL-PACKAGE */
GRANT SELECT ON SYS.USER_PROC_ARGUMENTS TO PUBLIC;

CREATE OR REPLACE VIEW SYS.USER_PACKAGE_ARGUMENTS AS
SELECT
	SYS.ORA_CASE_TRANS(P.PROC_NAME::VARCHAR2)::VARCHAR2(128) AS OBJECT_NAME,
	SYS.ORA_CASE_TRANS(P.PACKAGE_NAME::VARCHAR2)::VARCHAR2(128) AS PACKAGE_NAME,
	P.OID::VARCHAR2(10)::NUMBER AS OBJECT_ID,
	NULL::VARCHAR2(40) AS OVERLOAD,
	(P.FNO + 1)::NUMBER AS SUBPROGRAM_ID,
	CASE
	   WHEN SQ.ARGUMENT_NAME != '_NULL_' AND SQ.ARGUMENT_NAME != '_null_'
	        THEN SYS.ORA_CASE_TRANS(SQ.ARGUMENT_NAME::VARCHAR2)
	   ELSE
	        NULL
	END::VARCHAR2(128) AS ARGUMENT_NAME,
	SQ.POSITION::NUMBER AS POSITION,
	CASE
		WHEN P.KIND = 'f'
			THEN SQ.POSITION + 1
		ELSE SQ.POSITION
	END::NUMBER AS SEQUENCE,
	0::NUMBER AS DATA_LEVEL,
	CASE
	    /* Begin - ReqID:SRS-PLSQL-TYPE */
		WHEN SQ.TYPE_OBJECT_TYPE::VARCHAR2 = 'table' OR SQ.TYPE_OBJECT_TYPE::VARCHAR2 = 'TABLE'
		  OR SQ.TYPE_OBJECT_TYPE::VARCHAR2 = 'view' OR SQ.TYPE_OBJECT_TYPE::VARCHAR2 = 'VIEW'
		  THEN 'PL/SQL RECORD'
		/* End - ReqID:SRS-PLSQL-TYPE */
		WHEN SQ.DATA_TYPE = ANY(ARRAY['smallint', 'integer', 'bigint',
								   'numeric', 'number'])
			THEN 'NUMBER'
		WHEN SQ.DATA_TYPE = ANY(ARRAY['real', 'double precision'])
			THEN 'FLOAT'
		WHEN SQ.DATA_TYPE = 'bpchar'
			THEN 'CHAR'
		/* Begin - ReqID:SRS-PLSQL-RECORD */
		WHEN SQ.DATA_TYPE = 'orarecord'
		  THEN 'PL/SQL RECORD'
		/* End - ReqID:SRS-PLSQL-RECORD */
		ELSE ORA_CASE_TRANS(SQ.DATA_TYPE)::VARCHAR2(58)
	END::VARCHAR2(30) AS DATA_TYPE,
	CASE
		WHEN SQ.ARGDEFAULT = '_NULL_'
			THEN 'N'
		ELSE 'Y'
	END::VARCHAR2(1) AS DEFAULTED,
	NULL::LONG AS DEFAULT_VALUE,
	NULL::NUMBER AS DEFAULT_LENGTH,
	CASE
		WHEN SQ.IN_OUT = 'i' OR SQ.IN_OUT IS NULL
			THEN 'IN'
		WHEN SQ.IN_OUT = 'o'
			THEN 'OUT'
		WHEN SQ.IN_OUT = 'b'
			THEN 'IN/OUT'
		ELSE NULL
	END::VARCHAR2(9) AS IN_OUT,
	CASE
		/* Begin - ReqID:SRS-PLSQL-TYPE */
		WHEN SQ.DATA_LENGTH != 0
		    THEN SQ.DATA_LENGTH
		/* End - ReqID:SRS-PLSQL-TYPE */
		WHEN SQ.DATA_TYPE = ANY(ARRAY['smallint', 'integer', 'bigint',
								   'real', 'double precision',
								   'numeric', 'number'])
			THEN 22
		WHEN SQ.DATA_TYPE = ANY(ARRAY['long', 'long_raw'])
			THEN 32760
		ELSE NULL
	END::NUMBER AS DATA_LENGTH,
	CASE
		/* Begin - ReqID:SRS-PLSQL-TYPE */
		WHEN SQ.DATA_PRECISION != 0
		    THEN SQ.DATA_PRECISION
		/* End - ReqID:SRS-PLSQL-TYPE */
		WHEN SQ.DATA_TYPE = ANY(ARRAY['smallint', 'integer', 'bigint'])
			THEN 38
		WHEN SQ.DATA_TYPE = 'real'
			THEN 63
		WHEN SQ.DATA_TYPE = 'double precision'
			THEN 126
		WHEN SQ.DATA_TYPE = ANY(ARRAY['timestamp', 'timestamptz',
								   'oratimestamp', 'oratimestamptz',
								   'oratimestampltz'])
			THEN 6
		ELSE NULL
	END::NUMBER AS DATA_PRECISION,
	CASE
		/* Begin - ReqID:SRS-PLSQL-TYPE */
		WHEN SQ.DATA_SCALE != 0
		    THEN SQ.DATA_SCALE
		/* End - ReqID:SRS-PLSQL-TYPE */
		WHEN SQ.DATA_TYPE = ANY(ARRAY['real', 'double precision'])
			THEN -127
		ELSE NULL
	END::NUMBER AS DATA_SCALE,
	CASE
		WHEN SQ.DATA_TYPE= ANY(ARRAY['numeric', 'number',
								   'smallint', 'integer', 'bigint',
								   'real', 'double precision'])
			THEN 10
		ELSE NULL
	END::NUMBER AS RADIX,
	CASE
		WHEN SQ.DATA_TYPE::VARCHAR2(58) = ANY(ARRAY['char',
													  'character',
													  'varchar2',
													  'clob'])
			THEN 'CHAR_CS'
		WHEN SQ.DATA_TYPE::VARCHAR2(58) = ANY(ARRAY['nchar', 'nvarchar2',
													  'nclob'])
			THEN 'NCHAR_CS'
	END::VARCHAR2(44) AS CHARACTER_SET_NAME,
	NULL::VARCHAR2(128) AS TYPE_OWNER,
	/* Begin - ReqID:SRS-PLSQL-TYPE */
	CASE
		WHEN SQ.TYPE_NAME IS NOT NULL AND SQ.TYPE_NAME != '_NULL_' AND SQ.TYPE_NAME != '_null_'
		    THEN SYS.ORA_CASE_TRANS(SQ.TYPE_NAME)::VARCHAR2(128)
		ELSE NULL
	END::VARCHAR2(128) AS TYPE_NAME,
	/* End - ReqID:SRS-PLSQL-TYPE */
	NULL::VARCHAR2(128) AS TYPE_SUBNAME,
	NULL::VARCHAR2(128) AS TYPE_LINK,
	/* Begin - ReqID:SRS-PLSQL-TYPE */
	CASE
		WHEN SQ.TYPE_OBJECT_TYPE IS NOT NULL AND SQ.TYPE_OBJECT_TYPE != '_NULL_' AND SQ.TYPE_OBJECT_TYPE != '_null_'
		    THEN SYS.ORA_CASE_TRANS(SQ.TYPE_OBJECT_TYPE)::VARCHAR2(128)
		ELSE NULL
	END::VARCHAR2(128) AS TYPE_OBJECT_TYPE,
	CASE
		WHEN SQ.TYPE_OBJECT_TYPE = 'table' OR SQ.TYPE_OBJECT_TYPE = 'TABLE' OR SQ.TYPE_OBJECT_TYPE = 'view' OR SQ.TYPE_OBJECT_TYPE = 'VIEW'
			THEN 'ROWTYPE'
		ELSE NULL
	END::VARCHAR2(30) AS PLS_TYPE,
	/* End - ReqID:SRS-PLSQL-TYPE */
	CASE
		WHEN SQ.DATA_TYPE::VARCHAR2(58) = ANY(ARRAY['char',
													  'character',
													  'varchar2'])
			THEN NULL
		ELSE 0
	END::NUMBER AS CHAR_LENGTH,
	CASE
		WHEN SQ.DATA_TYPE::VARCHAR2(58) = ANY(ARRAY['char',
													  'character',
													  'varchar2'])
			THEN 'B'
		ELSE '0'
	END::VARCHAR2(1) AS CHAR_USED,
	0::VARCHAR2(256) AS ORIGIN_CON_ID
FROM
	PG_GET_SUBPROCS_IN_PACKAGE() AS P
	LEFT JOIN
	(
		SELECT
			OID,
			FNO,
			UNNEST(ARGNAMES) AS ARGUMENT_NAME,
			UNNEST(ARGTYPENAMES) AS DATA_TYPE,
			UNNEST(ARGMODES) AS IN_OUT,
			UNNEST(ARGDEFAULTS) AS ARGDEFAULT,
			GENERATE_SERIES(0, NARGS) AS POSITION,
			/* Begin - ReqID:SRS-PLSQL-TYPE */
			UNNEST(TYPE_NAMES) AS TYPE_NAME,
			UNNEST(TYPE_OBJECT_TYPES) AS TYPE_OBJECT_TYPE,
			UNNEST(DATA_LENGTHS) AS DATA_LENGTH,
			UNNEST(DATA_PRECISIONS) AS DATA_PRECISION,
			UNNEST(DATA_SCALES) AS DATA_SCALE
			/* End - ReqID:SRS-PLSQL-TYPE */
		FROM
			PG_GET_SUBPROCS_IN_PACKAGE() WHERE KIND = 'f'
		UNION ALL
		SELECT
			OID,
			FNO,
			UNNEST(ARGNAMES) AS ARGUMENT_NAME,
			UNNEST(ARGTYPENAMES) AS DATA_TYPE,
			UNNEST(ARGMODES) AS IN_OUT,
			UNNEST(ARGDEFAULTS) AS ARGDEFAULT,
			GENERATE_SERIES(1, NARGS) AS POSITION,
			/* Begin - ReqID:SRS-PLSQL-TYPE */
			UNNEST(TYPE_NAMES) AS TYPE_NAME,
			UNNEST(TYPE_OBJECT_TYPES) AS TYPE_OBJECT_TYPE,
			UNNEST(DATA_LENGTHS) AS DATA_LENGTH,
			UNNEST(DATA_PRECISIONS) AS DATA_PRECISION,
			UNNEST(DATA_SCALES) AS DATA_SCALE
			/* End - ReqID:SRS-PLSQL-TYPE */
		FROM
			PG_GET_SUBPROCS_IN_PACKAGE() WHERE NARGS > 0 AND KIND = 'p'
	) AS SQ
		ON P.OID = SQ.OID AND P.FNO = SQ.FNO
WHERE
	SQ.POSITION IS NOT NULL
	AND P.NAMESPACE <> 'PG_CATALOG'::REGNAMESPACE::OID
	AND P.NAMESPACE <> 'PG_TOAST'::REGNAMESPACE::OID
	AND P.NAMESPACE <> 'INFORMATION_SCHEMA'::REGNAMESPACE::OID
	AND PG_GET_USERBYID(P.OWNER) = CURRENT_USER	/* BUG#M0000074 */
ORDER BY
	OBJECT_ID,OBJECT_NAME
;

GRANT SELECT ON SYS.USER_PACKAGE_ARGUMENTS TO PUBLIC;

CREATE OR REPLACE VIEW SYS.USER_ARGUMENTS AS
	SELECT * FROM SYS.USER_PROC_ARGUMENTS --come from pg_proc
UNION ALL
	SELECT * FROM SYS.USER_PACKAGE_ARGUMENTS --come from pg_package
ORDER BY
	OBJECT_ID,OBJECT_NAME
;
/* End - ReqID:SRS-SQL-PACKAGE */

/* GRANT SELECT PRIVILEGE TO PUBLIC */
GRANT SELECT ON SYS.USER_ARGUMENTS TO PUBLIC;

/* Begin - ReqID:SRS-SQL-SEQ */
/* For sequence VIEWS */
CREATE OR REPLACE VIEW SYS.DBA_SEQUENCES AS
SELECT
	c.relowner::regrole AS sequence_owner,c.relname AS sequence_name,s.seqmin AS min_value,s.seqmax AS max_value,
	s.seqincrement AS increment_by,s.seqcycle AS cycle_flag,null AS order_flag,s.seqcache AS cache_size,
	CASE
		WHEN has_sequence_privilege(c.oid, 'SELECT,USAGE'::text)
			THEN pg_sequence_last_value(c.oid::regclass)
		ELSE NULL::bigint
	END AS last_number,
	decode(bitand(s.flags, 16), 16, 'Y', 'N') AS scale_flag,
	decode(bitand(s.flags, 2048), 2048, 'Y', 'N') AS extend_flag,null AS shared_flag,
	decode(bitand(s.flags, 64), 64, 'Y', 'N') AS session_flag,null AS keep_value
	FROM PG_SEQUENCE s,pg_class c where s.seqrelid = c.oid AND NOT pg_is_other_temp_schema(c.relnamespace); /* BUG#M0000310 */

/* Begin BUG#Z228 */
/* GRANT SELECT PRIVILEGE TO PUBLIC */
GRANT SELECT ON SYS.DBA_SEQUENCES TO PUBLIC;
/* End BUG#Z228 */

CREATE OR REPLACE VIEW SYS.ALL_SEQUENCES AS
SELECT
	c.relowner::regrole AS sequence_owner,c.relname AS sequence_name,s.seqmin AS min_value,s.seqmax AS max_value,
	s.seqincrement AS increment_by,s.seqcycle AS cycle_flag,null AS order_flag,s.seqcache AS cache_size,
	CASE
		WHEN has_sequence_privilege(c.oid, 'SELECT,USAGE'::text)
			THEN pg_sequence_last_value(c.oid::regclass)
		ELSE NULL::bigint
	END AS last_number,
	decode(bitand(s.flags, 16), 16, 'Y', 'N') AS scale_flag,
	decode(bitand(s.flags, 2048), 2048, 'Y', 'N') AS extend_flag,null AS shared_flag,
	decode(bitand(s.flags, 64), 64, 'Y', 'N') AS session_flag,null AS keep_value
	FROM PG_SEQUENCE s,pg_class c where s.seqrelid = c.oid AND NOT pg_is_other_temp_schema(c.relnamespace); /* BUG#M0000310 */

/* Begin BUG#Z228 */
/* GRANT SELECT PRIVILEGE TO PUBLIC */
GRANT SELECT ON SYS.ALL_SEQUENCES TO PUBLIC;
/* End BUG#Z228 */

CREATE OR REPLACE VIEW SYS.USER_SEQUENCES AS
SELECT
	c.relname AS sequence_name,s.seqmin AS min_value,s.seqmax AS max_value,
	s.seqincrement AS increment_by,s.seqcycle AS cycle_flag,null AS order_flag,s.seqcache AS cache_size,
	CASE
		WHEN has_sequence_privilege(c.oid, 'SELECT,USAGE'::text)
			THEN pg_sequence_last_value(c.oid::regclass)
		ELSE NULL::bigint
	END AS last_number,
	decode(bitand(s.flags, 16), 16, 'Y', 'N') AS scale_flag,
	decode(bitand(s.flags, 2048), 2048, 'Y', 'N') AS extend_flag,null AS shared_flag,
	decode(bitand(s.flags, 64), 64, 'Y', 'N') AS session_flag,null AS keep_value
	FROM PG_SEQUENCE s,pg_class c where s.seqrelid = c.oid and pg_get_userbyid(c.relowner) = CURRENT_USER
	AND NOT pg_is_other_temp_schema(c.relnamespace); /* BUG#M0000310 */

/* Begin BUG#Z228 */
/* GRANT SELECT PRIVILEGE TO PUBLIC */
GRANT SELECT ON SYS.USER_SEQUENCES TO PUBLIC;
/* End BUG#Z228 */
/* End - ReqID:SRS-SQL-SEQ */
/* Begin - ReqID:SRS-SQL-FORCEVIEW */
CREATE OR REPLACE VIEW SYS.DBA_VIEWS AS
	SELECT
		SYS.ORA_CASE_TRANS(
			PG_GET_USERBYID(RELOWNER)::VARCHAR2
		)::VARCHAR2(128) AS OWNER,
		SYS.ORA_CASE_TRANS(RELNAME::VARCHAR2)::VARCHAR2(128) AS VIEW_NAME,
		LENGTH(pg_get_viewdef(OID))::NUMBER(38) AS TEXT_LENGTH,
		pg_get_viewdef(OID)::TEXT AS TEXT,
		pg_get_viewdef(OID)::VARCHAR2(4000) AS TEXT_VC,
		NULL::NUMBER(38) AS TYPE_TEXT_LENGTH,
		NULL::VARCHAR2(4000) AS TYPE_TEXT,
		NULL::NUMBER(38) AS OID_TEXT_LENGTH,
		NULL::VARCHAR2(4000) AS OID_TEXT,
		NULL::VARCHAR2(128) AS VIEW_TYPE_OWNER,
		NULL::VARCHAR2(128) AS VIEW_TYPE,
		NULL::VARCHAR2(128) AS SUPERVIEW_NAME,
		NULL::VARCHAR2(1) AS EDITIONING_VIEW,
		NULL::VARCHAR2(1) AS READ_ONLY,
		NULL::VARCHAR2(1) AS CONTAINER_DATA,
		NULL::VARCHAR2(12) AS BEQUEATH,
		0::VARCHAR2(256) AS ORIGIN_CON_ID,
		NULL::VARCHAR2(100) AS DEFAULT_COLLATION,
		NULL::VARCHAR2(3) AS CONTAINERS_DEFAULT,
		NULL::VARCHAR2(3) AS CONTAINER_MAP,
		NULL::VARCHAR2(3) AS EXTENDED_DATA_LINK,
		NULL::VARCHAR2(3) AS EXTENDED_DATA_LINK_MAP,
		NULL::VARCHAR2(3) AS HAS_SENSITIVE_COLUMN,
		NULL::VARCHAR2(3) AS ADMIT_NULL,
		NULL::VARCHAR2(3) AS PDB_LOCAL_ONLY
	FROM
		PG_CLASS
	WHERE
		RELKIND = 'v';
GRANT SELECT ON SYS.DBA_VIEWS TO PUBLIC;

