		NULL::VARCHAR2(128) AS SUPERVIEW_NAME,
		NULL::VARCHAR2(1) AS EDITIONING_VIEW,
		NULL::VARCHAR2(1) AS READ_ONLY,
		NULL::VARCHAR2(1) AS CONTAINER_DATA,
		NULL::VARCHAR2(12) AS BEQUEATH,
		0::VARCHAR2(256) AS ORIGIN_CON_ID,
