/* Begin - ReqID:SRS-PLSQL-CURSOR */
CREATE VIEW sys.v$open_cursor AS
 SELECT saddr::raw(8) AS saddr,
 sid::number AS sid,
 SYS.ORA_CASE_TRANS(user_name)::varchar2(128) AS user_name,
 address::raw(8) AS address,
 hash_value::number AS hash_value,
 sql_id::varchar2(13) AS sql_id,
 sql_text::varchar2(60) AS sql_text,
 last_sql_active_time::DATE AS last_sql_active_time,
 sql_exec_id::number AS sql_exec_id,
 cursor_type::varchar2(64),
 child_address::raw(8) AS child_address,
 con_id::number AS con_id
 FROM ora_open_cursors();
GRANT SELECT ON sys.v$open_cursor TO public;
/* End - ReqID:SRS-PLSQL-CURSOR */

/* Begin - ReqID:SRS-SQL-DBLINK */
CREATE OR REPLACE VIEW sys.ivorysql_dblink as
   SELECT t.lnkname,
    t.lnkowner,
    t.lnkowneroid,
        CASE
            WHEN t.fdwname = 'postgres_fdw'::name THEN 1::oid
            WHEN t.fdwname = 'oracle_fdw'::name THEN 0::oid
            ELSE t.fdwoid
        END AS lnktype,
    t.lnkispublic,
    (SELECT substring(__unnamed_subquery_0.option, length('user='::text) + 1) AS "substring"
           FROM ( SELECT unnest(t.umoptions) AS option) __unnamed_subquery_0
          WHERE __unnamed_subquery_0.option ~~ 'user=%'::text) AS lnkuser,
    '********'::text AS lnkpassword,
    t.lnkconnstr,
    t.lnkacl,
    t.srvoid AS oid,
    t.lnkcreated
   FROM ( SELECT srv.srvname AS lnkname,
            aut.rolname AS lnkowner,
            srv.srvowner AS lnkowneroid,
            true AS lnkispublic,
            srv.olnkusingstring as lnkconnstr,
            srv.srvacl AS lnkacl,
            srv.oid AS srvoid,
            ums.umoptions,
            srv.srvoptions,
            fdw.fdwname,
            fdw.oid AS fdwoid,
            ob.created AS lnkcreated
           FROM pg_foreign_server srv
             JOIN pg_foreign_data_wrapper fdw ON fdw.oid = srv.srvfdw
             LEFT JOIN pg_user_mapping um ON um.umserver = srv.oid AND um.umuser = 0::oid
             LEFT JOIN pg_user_mappings ums ON ums.srvname = srv.srvname AND ums.umuser = 0::oid
             LEFT JOIN pg_authid aut ON aut.oid = srv.srvowner
             LEFT JOIN pg_object ob ON ob.obj_oid = srv.oid
          WHERE srv.olnkispublic = true and srv.olnkconntype != 0
        UNION ALL
         SELECT srv.srvname AS lnkname,
            aut.rolname AS lnkowner,
            srv.srvowner AS lnkowneroid,
            false AS lnkispublic,
            srv.olnkusingstring as lnkconnstr,
            srv.srvacl AS lnkacl,
            srv.oid AS srvoid,
            ums.umoptions,
            srv.srvoptions,
            fdw.fdwname,
            fdw.oid AS fdwoid,
            ob.created AS lnkcreated
           FROM pg_foreign_server srv
             JOIN pg_foreign_data_wrapper fdw ON fdw.oid = srv.srvfdw
             LEFT JOIN pg_user_mapping um ON um.umserver = srv.oid AND um.umuser = srv.srvowner
             LEFT JOIN pg_user_mappings ums ON ums.srvname = srv.srvname AND ums.umuser != 0::oid
             LEFT JOIN pg_authid aut ON aut.oid = srv.srvowner
             LEFT JOIN pg_object ob ON ob.obj_oid = srv.oid
          WHERE srv.olnkispublic = false and srv.olnkconntype != 0) t;
GRANT SELECT ON SYS.ivorysql_dblink TO PUBLIC;
--
-- ALL_DB_LINKS
--
CREATE OR REPLACE VIEW sys.ALL_DB_LINKS as
 SELECT i.lnkowner::VARCHAR2(12) AS owner,
    i.lnkname::VARCHAR2(128) AS db_link,
    i.lnkuser::VARCHAR2(128) AS username,
    NULL::VARCHAR2(128) AS credential_name,
    NULL::VARCHAR2(128) AS credential_owner,
    i.lnkconnstr::VARCHAR2(2000) AS host,
    i.lnkcreated::TIMESTAMP(0)::DATE AS created,
    'no'::VARCHAR2(3) AS hidden,
    'no'::VARCHAR2(3) AS shard_internal,
    'yes'::VARCHAR2(3) AS valid,
    'no'::VARCHAR2(3) AS intra_cdb
   FROM ivorysql_dblink i
  WHERE i.lnkispublic = true OR has_server_privilege(i.oid, 'USAGE'::text);
GRANT SELECT ON SYS.ALL_DB_LINKS TO PUBLIC;
--
-- USER_DB_LINKS
--
CREATE OR REPLACE VIEW sys.USER_DB_LINKS as
 SELECT i.lnkname::VARCHAR2(128) AS db_link,
    i.lnkuser::VARCHAR2(128) AS username,
    i.lnkpassword::VARCHAR2(128) AS password,
    NULL::VARCHAR2(128) AS credential_name,
    NULL::VARCHAR2(128) AS credential_owner,
    i.lnkconnstr::VARCHAR2(2000) AS host,
    i.lnkcreated::TIMESTAMP(0)::DATE AS created,
    'no'::VARCHAR2(3) AS hidden,
    'no'::VARCHAR2(3) AS shard_internal,
    'yes'::VARCHAR2(3) AS valid,
    'no'::VARCHAR2(3) AS intra_cdb
   FROM ivorysql_dblink i
  WHERE pg_get_userbyid(i.lnkowneroid) = current_user AND i.lnkispublic = false;
GRANT SELECT ON SYS.USER_DB_LINKS TO PUBLIC;
--
-- DBA_DB_LINKS
--
CREATE OR REPLACE VIEW sys.DBA_DB_LINKS as
 SELECT
    i.lnkowner::VARCHAR2(12) AS owner,
    i.lnkname::VARCHAR2(128) AS db_link,
    i.lnkuser::VARCHAR2(128) AS username,
    NULL::VARCHAR2(128) AS credential_name,
    NULL::VARCHAR2(128) AS credential_owner,
    i.lnkconnstr::VARCHAR2(2000) AS host,
    i.lnkcreated::TIMESTAMP(0)::DATE AS created,
    'no'::VARCHAR2(3) AS hidden,
    'no'::VARCHAR2(3) AS shard_internal,
    'yes'::VARCHAR2(3) AS valid,
    'no'::VARCHAR2(3) AS intra_cdb
   FROM ivorysql_dblink i;
GRANT SELECT ON SYS.DBA_DB_LINKS TO PUBLIC;
--
-- V$DBLINK
--

CREATE OR REPLACE VIEW sys.V$DBLINK as
  SELECT DISTINCT
    i.lnkname::VARCHAR2(128) as DB_LINK,
    (SELECT oid from pg_roles WHERE rolname = session_user)::INT8::NUMBER as OWNER_ID,
    'yes'::VARCHAR2(3) as LOGGED_ON,
    'no'::VARCHAR2(3) as HETEROGENEOUS,
    'unkn'::VARCHAR2(6) as PROTOCOL,
    1::NUMBER AS OPEN_CURSORS,
    'yes'::VARCHAR2(3) as IN_TRANSACTION,
    'no'::VARCHAR2(3) as UPDATE_SENT,
    1::NUMBER as COMMIT_POINT_STRENGTH,
    1::NUMBER as CON_ID
  FROM sys.ivorysql_dblink i LEFT JOIN pg_foreign_table f ON  f.ftserver = i.oid LEFT JOIN pg_class c ON c.oid = f.ftrelid
   LEFT JOIN pg_namespace n ON c.relnamespace = n.oid
   WHERE  n.nspname LIKE 'pg_temp%' AND
      n.nspname = (SELECT nspname
                   FROM pg_namespace
                   WHERE oid = pg_my_temp_schema());
GRANT SELECT ON SYS.V$DBLINK TO PUBLIC;

--
-- GV$DBLINK
--
CREATE OR REPLACE VIEW sys.GV$DBLINK as
  SELECT DISTINCT
  1::NUMBER as INST_ID,
    i.lnkname::VARCHAR2(128) as DB_LINK,
    (SELECT oid from pg_roles WHERE rolname = session_user)::INT8::NUMBER as OWNER_ID,
    'yes'::VARCHAR2(3) as LOGGED_ON,
    'no'::VARCHAR2(3) as HETEROGENEOUS,
    'unkn'::VARCHAR2(6) as PROTOCOL,
    1::NUMBER AS OPEN_CURSORS,
    'yes'::VARCHAR2(3) as IN_TRANSACTION,
    'no'::VARCHAR2(3) as UPDATE_SENT,
    1::NUMBER as COMMIT_POINT_STRENGTH,
    1::NUMBER as CON_ID
  FROM sys.ivorysql_dblink i LEFT JOIN pg_foreign_table f ON  f.ftserver = i.oid LEFT JOIN pg_class c ON c.oid = f.ftrelid
   LEFT JOIN pg_namespace n ON c.relnamespace = n.oid
   WHERE  n.nspname LIKE 'pg_temp%' AND
      n.nspname = (SELECT nspname
                   FROM pg_namespace
                   WHERE oid = pg_my_temp_schema());
GRANT SELECT ON SYS.GV$DBLINK TO PUBLIC;

--
-- DBA_DB_LINK_SOURCES
--

CREATE OR REPLACE VIEW sys.dba_db_link_sources AS
SELECT
    1::NUMBER AS source_id,
    d.datname::VARCHAR2(256) AS db_name,
    d.oid::INT4::NUMBER AS dbid,
    d.datname::VARCHAR2(256) AS db_unique_name,
    (SELECT ivy_get_host_name())::VARCHAR2(256) AS host_name,
    (SELECT (string_to_array(ivy_get_host_ipv4, ' '))[1])::VARCHAR2(128) AS ip_address,
    'tcp'::VARCHAR2(64) AS protocol,
    (SELECT current_user)::VARCHAR2(128) AS username,
    iu.oid::INT4::NUMBER AS "user#",
    current_timestamp::TIMESTAMP(6) AS first_logon_time,
    current_timestamp::TIMESTAMP(6) AS last_logon_time,
    1::NUMBER AS logon_count
FROM
    pg_roles iu, pg_database d
    WHERE iu.rolname = current_user AND d.datname = current_database;
GRANT SELECT ON SYS.dba_db_link_sources TO PUBLIC;
/* End - ReqID:SRS-SQL-DBLINK */

/* Begin - ReqID:SRS-SQL-TRIGGER */
--
-- ALL_TRIGGERS
--
CREATE OR REPLACE VIEW sys.all_triggers AS
SELECT
    SYS.ORA_CASE_TRANS(usr.usename::varchar2)::varchar2(128) AS owner,
    SYS.ORA_CASE_TRANS(trg.tgname::varchar2)::varchar2(128)  AS trigger_name,
    CASE
        WHEN cls.relkind = 'v' THEN 'INSTEAD OF'
        WHEN trg.tgtype & 2 <> 0 THEN
            CASE
                WHEN trg.tgtype & 1 <> 0 THEN 'BEFORE EACH ROW'
                ELSE 'BEFORE STATEMENT'
            END
        WHEN trg.tgtype & 2 = 0 THEN
            CASE
                WHEN trg.tgtype & 1 <> 0 THEN 'AFTER EACH ROW'
                ELSE 'AFTER STATEMENT'
            END
        ELSE 'UNKNOWN'
    END::varchar2(16)                       AS trigger_type,

	/* Begin - BUG#Z7179 */
    CONCAT_WS(' OR ',
            CASE WHEN trg.tgtype & (1 << 2) <> 0 THEN 'INSERT' END,
            CASE WHEN trg.tgtype & (1 << 3) <> 0 THEN 'DELETE' END,
            CASE WHEN trg.tgtype & (1 << 4) <> 0 THEN 'UPDATE' END,
            CASE WHEN trg.tgtype & (1 << 5) <> 0 THEN 'TRUNCATE' END
    )::varchar2(246)                        AS triggering_event,
	/* End - BUG#Z7179 */

    SYS.ORA_CASE_TRANS(usr.usename::varchar2)::varchar2(128)              AS table_owner,
	/* Begin - BUG#Z6216 */
	CASE
		WHEN cls.relkind = 'v' THEN 'VIEW'
		ELSE 'TABLE'
	END::varchar2(18)                   AS base_object_type,
	/* Begin - BUG#Z6216 */
    SYS.ORA_CASE_TRANS(cls.relname::varchar2)::varchar2(128)              AS table_name,

    NULL::varchar2(4000)                    AS column_name,

    CASE
        WHEN obj.obj_oid IS NOT NULL AND jsonb_typeof(obj.option->'referencing') = 'array' THEN
            CONCAT (
                'REFERENCING ',
                (
                 SELECT string_agg(elem, ' ')
                 FROM jsonb_array_elements_text(obj.option->'referencing') AS elem
                )
            )
        ELSE 'REFERENCING NEW AS NEW OLD AS OLD'	/* BUG#Z7179 */
    END::varchar2(422) AS referencing_names,

	WHEN_CLAUSE.when_expr::varchar2(4000) AS when_clause, /* BUG#Z6822 */

	CASE
		WHEN trg.tgenabled = 'O' THEN 'ENABLED'
		WHEN trg.tgenabled = 'A' THEN 'ENABLED'
		WHEN trg.tgenabled = 'D' THEN 'DISABLED'
		ELSE 'UNKNOWN'
	END::varchar2(8) AS status,

    CONCAT('TRIGGER ',
      SYS.ORA_CASE_TRANS(trg.tgname::varchar2),
      ' ON ',
      SYS.ORA_CASE_TRANS(cls.relname::varchar2))::varchar2(4000) AS description,

    SYS.ORA_CASE_TRANS(lang.lanname::varchar2)::varchar2(11)      AS action_type,
    SYS.ORA_CASE_TRANS(p.prosrc::varchar2)::long                  AS trigger_body,

    'NO'::varchar2(7)               AS crossedition,	/* BUG#Z6339 */

    /* Begin - BUG#Z7179 */
    'NO'::varchar2(3) AS before_statement,
    'NO'::varchar2(3) AS before_row,
    'NO'::varchar2(3) AS after_row,
    'NO'::varchar2(3) AS after_statement,
    'NO'::varchar2(3) AS instead_of_row,
    /* End - BUG#Z7179 */

    'YES'::varchar2(3)                 AS fire_once,
    'NO'::varchar2(3)                  AS apply_server_only

FROM
    pg_trigger trg
JOIN pg_class cls
    ON trg.tgrelid = cls.oid
JOIN pg_user usr
    ON usr.usesysid = cls.relowner
LEFT JOIN pg_proc p
    ON trg.tgfoid = p.oid
LEFT JOIN pg_language lang
    ON p.prolang = lang.oid
LEFT JOIN pg_object obj
    ON obj.obj_oid = trg.oid
/* Begin - BUG#Z6822 */
LEFT JOIN LATERAL (
	SELECT
		trim(
			(regexp_match(
				pg_get_triggerdef(trg.oid, true), '(?s)WHEN\s*\((.*?)\)\s*BEGIN'))[1]
		) AS when_expr
) WHEN_CLAUSE ON true
/* End - BUG#Z6822 */
WHERE
    NOT trg.tgisinternal;

GRANT SELECT ON sys.all_triggers TO PUBLIC;

--
-- USER_TRIGGERS
--
CREATE OR REPLACE VIEW sys.user_triggers AS
 SELECT at.trigger_name AS trigger_name,
	at.trigger_type AS trigger_type,
	at.triggering_event AS triggering_event,
	at.table_owner AS table_owner,
	at.base_object_type AS base_object_type,
	at.table_name AS table_name,
	at.column_name AS column_name,
	at.referencing_names AS referencing_names,
	at.when_clause AS when_clause,
	at.status AS status,
	at.description AS description,
	at.action_type AS action_type,
	at.trigger_body AS trigger_body,
	at.crossedition AS crossedition, /* BUG#Z6339 */
	at.before_statement AS before_statement,
	at.before_row AS before_row,
	at.after_row AS after_row,
	at.after_statement AS after_statement,
	at.instead_of_row AS instead_of_row,
	at.fire_once AS fire_once,
	at.apply_server_only AS apply_server_only
   FROM sys.all_triggers at
 WHERE at.owner::regrole = current_user::regrole;	/* BUG#Z6215 */

GRANT SELECT ON sys.user_triggers TO PUBLIC;

--
-- DBA_TRIGGERS
--
CREATE OR REPLACE VIEW sys.dba_triggers AS
 SELECT * FROM sys.all_triggers;

GRANT SELECT ON sys.dba_triggers TO PUBLIC;
/* End - ReqID:SRS-SQL-TRIGGER */

/* Begin - ReqID: RQ-SQL-SYSVIEW */
/* *******************************************************************************************
                                          XXX_TABLES
* *******************************************************************************************/
CREATE OR REPLACE VIEW SYS.TABLES_INTERNAL AS
    SELECT
        c.oid AS oid,
        SYS.ORA_CASE_TRANS(PG_GET_USERBYID(c.relowner)::varchar2)::varchar2(128) AS owner,
        SYS.ORA_CASE_TRANS(c.relname::VARCHAR2)::VARCHAR2(128) AS table_name,
        SYS.ORA_CASE_TRANS(
            COALESCE(
                ((SELECT spcname FROM pg_tablespace WHERE oid = c.reltablespace)::VARCHAR2),
                'pg_default')
        )::varchar2(30) AS tablespace_name,
        NULL::varchar2(128) AS cluster_name,
        NULL::varchar2(128) AS iot_name,
        'VALID'::varchar2(8) AS status,
        COALESCE(
            (100 - (SELECT split_part(opt, '=', 2)::integer
             FROM unnest(c.reloptions) AS opt
             WHERE split_part(opt, '=', 1) = 'fillfactor')),
            0
        )::number AS pct_free,
        NULL::number AS pct_used,
        NULL::number AS ini_trans,
        NULL::number AS max_trans,
        NULL::number AS initial_extent,
        NULL::number AS next_extent,
        NULL::number AS min_extents,
        NULL::number AS max_extents,
        NULL::number AS pct_increase,
        NULL::number AS freelists,
        NULL::number AS freelist_groups,
        CASE
            WHEN c.relpersistence = 'p' THEN 'YES'
            ELSE 'NO'
        END::varchar2(3) AS logging,
        'N'::varchar2(1) AS backed_up,
        CASE
            WHEN c.reltuples > -1 THEN c.reltuples
            ELSE NULL
        END::number AS num_rows,
        CASE
            WHEN c.relpages > -1 THEN c.relpages
            ELSE NULL
        END::number AS blocks,
        NULL::number AS empty_blocks,
        NULL::number AS avg_space,
        NULL::number AS chain_cnt,
        (SELECT SUM(stawidth) FROM pg_statistic WHERE starelid = c.oid LIMIT 1)::number AS avg_row_len,
        NULL::number AS avg_space_freelist_blocks,
        NULL::number AS num_freelist_blocks,
        NULL::varchar2(10) AS degree,
        NULL::varchar2(10) AS instances,
        NULL::varchar2(5) AS cache,
        'ENABLED'::varchar2(8) AS table_lock,
        NULL::number AS sample_size,
        /* Begin - bug#7760 */
        TO_CHAR(COALESCE(GREATEST(
                pg_stat_get_last_analyze_time(c.oid),
                pg_stat_get_last_autoanalyze_time(c.oid)
        ), pg_stat_get_last_analyze_time(c.oid),
        pg_stat_get_last_autoanalyze_time(c.oid)), current_setting('nls_date_format'))::date AS last_analyzed,
        /* End - bug#7760 */
        CASE
            WHEN c.relkind = 'p' THEN 'YES'
            ELSE 'NO'
        END::varchar2(3) AS partitioned,
        NULL::varchar2(12) AS iot_type,
        CASE
            WHEN c.relpersistence IN ('t', 'g') THEN 'Y'
            ELSE 'N'
        END::varchar2(1) AS temporary,
        'N'::varchar2(1) AS secondary,
        'NO'::varchar2(3) AS nested,
        NULL::varchar2(7) AS buffer_pool,
        NULL::varchar2(7) AS flash_cache,
        NULL::varchar2(7) AS cell_flash_cache,
        'ENABLED'::varchar2(8) AS row_movement,
        'YES'::varchar2(3) AS global_stats,
        'NO'::varchar2(3) AS user_stats,
        CASE
            WHEN c.relpersistence IN ('t', 'g') THEN
                CASE
                    WHEN EXISTS (SELECT 1
                                    FROM unnest(c.reloptions) AS op
                                WHERE
                                    (regexp_match(op, 'on_commit_delete_rows=true') IS NOT NULL)
                                    OR (regexp_match(op, 'on_commit_drop=true') IS NOT NULL))
                        THEN 'SYS$TRANSACTION'
                    ELSE 'SYS$SESSION'
                END
            ELSE NULL
        END::varchar2(15) AS duration,
        CASE
            WHEN current_setting('zero_damaged_pages') = 'off' THEN 'DISABLED'
            ELSE 'ENABLED'
        END::varchar2(8) AS skip_corrupt,
        NULL::varchar2(3) AS monitoring,
        NULL::varchar2(128) AS cluster_owner,
        'DISABLED'::varchar2(8) AS dependencies,
        'DISABLED'::varchar2(8) AS compression,
        NULL::varchar2(30) AS compress_for,
        'NO'::varchar2(3) AS dropped,
        NULL::varchar2(3) AS read_only,
        NULL::varchar2(3) AS segment_created,
        NULL::varchar2(7) AS result_cache,
        'NO'::varchar2(3) AS clustering,
        NULL::varchar2(23) AS activity_tracking,
        NULL::varchar2(25) AS dml_timestamp,
        CASE
           WHEN EXISTS (select 1 from pg_attribute where attrelid = c.oid and attidentity IN ('a', 'd', 'n', 'i', 'o')) THEN 'YES'
           ELSE 'NO'
        END::varchar2(3) AS has_identity,
        'NO'::varchar2(3) AS container_data,
        'DISABLED'::varchar2(8) AS inmemory,
        NULL::varchar2(8) AS inmemory_priority,
        NULL::varchar2(15) AS inmemory_distribute,
        NULL::varchar2(17) AS inmemory_compression,
        NULL::varchar2(13) AS inmemory_duplicate,
        UPPER((SELECT collname FROM pg_collation WHERE oid = (obj.option->>'collation')))::varchar2(100) AS default_collation,
        'N'::varchar2(1) AS duplicated,
        'N'::varchar2(1) AS sharded,
        'N'::varchar2(1) AS externally_sharded,
        'N'::varchar2(1) AS externally_duplicated,
        CASE
            WHEN c.relkind = 'f' THEN 'YES'
            ELSE 'NO'
        END::varchar2(3) AS external,
        'NO'::varchar2(3) AS hybrid,
        NULL::varchar2(24) AS cellmemory,
        'NO'::varchar2(3) AS containers_default,
        'NO'::varchar2(3) AS container_map,
        'NO'::varchar2(3) AS extended_data_link,
        NULL::varchar2(3) AS extended_data_link_map,
        NULL::varchar2(12) AS inmemory_service,
        NULL::varchar2(1000) AS inmemory_service_name,
        'NO'::varchar2(3) AS container_map_object,
        'DISABLED'::varchar2(8) AS memoptimize_read,
        NULL::varchar2(8) AS memoptimize_write,
        'NO'::varchar2(3) AS has_sensitive_column,
        'NO'::varchar2(3) AS admit_null,
        'YES'::varchar2(3) AS data_link_dml_enabled,
        CASE
            WHEN EXISTS (SELECT 1 FROM pg_subscription_rel WHERE srrelid = c.oid)
                OR EXISTS (SELECT 1 FROM pg_publication_rel WHERE prrelid = c.oid) THEN 'ENABLED'
            ELSE 'DISABLED'
        END::varchar2(8) AS logical_replication
    FROM
        pg_class c
    LEFT JOIN
        pg_object obj ON c.oid = obj.obj_oid
    WHERE
        c.relkind IN ('r', 'p', 'f')
        AND c.oid NOT IN (SELECT rcyrelid FROM pg_recyclebin)
        AND c.oid NOT IN (SELECT inhrelid FROM pg_inherits);

