        NULL::number AS namespace,
        NULL::varchar2(128) AS edition_name,
        NULL::varchar2(18) AS sharing,
        NULL::varchar2(1) AS editionable,
        'N'::varchar2(1) AS oracle_maintained,
        'N'::varchar2(1) AS application,
