    SELECT
        SYS.ORA_CASE_TRANS(PG_GET_USERBYID(opr.oprowner)::varchar2)::varchar2(128) AS owner,
        SYS.ORA_CASE_TRANS(opr.oprname::varchar2)::varchar2(128) AS object_name,
