        NULL::number AS created_appid,
        NULL::number AS created_vsnid,
        NULL::number AS modified_appid,
        NULL::number AS modified_vsnid
    FROM
        pg_trigger tg
    LEFT JOIN
        pg_class c ON tg.tgrelid = c.oid
    WHERE
        c.relowner::regrole = current_user::regrole

UNION ALL
