        LEFT JOIN
            pg_class ci ON cons.conindid = ci.oid
        WHERE
            c.relowner::regrole = current_user::regrole
    UNION ALL
        SELECT
            SYS.ORA_CASE_TRANS(PG_GET_USERBYID(c.relowner)::VARCHAR2)::VARCHAR2(128) AS owner,
            (SYS.ORA_CASE_TRANS((c.relname || '_' || attr.attname)::varchar2) || '_NOT_NULL')::varchar2(128) AS constraint_name,
            'C'::varchar2(1) AS constraint_type,
            SYS.ORA_CASE_TRANS(c.relname::varchar2)::varchar2(128) AS table_name,
            (('"' || UPPER(attr.attname)::varchar2) || '" IS NOT NULL')::long AS search_condition,
            (('"' || UPPER(attr.attname)::varchar2) || '" IS NOT NULL')::varchar2(4000) AS search_condition_vc,
            NULL::VARCHAR2(128) AS r_owner,
            NULL::varchar2(128) AS r_constraint_name,
            NULL::varchar2(11) AS delete_rule,
            'ENABLED'::varchar2(8) AS status,
            'NOT DEFERRABLE'::varchar2(14) AS condeferrable,
            'IMMEDIATE'::varchar2(9) AS deferred,
            'VALIDATE'::varchar2(13) AS validate,
            'USER NAME'::varchar2(14) AS generated,
            NULL::varchar2(3) AS bad,
            NULL::varchar2(4) AS rely,
            NULL::date AS last_change,
            NULL::VARCHAR2(128) AS index_owner,
            NULL::varchar2(128) AS index_name,
            NULL::varchar2(7) AS invalid,
            NULL::varchar2(14) AS view_related,
            NULL::number AS origin_con_id
        FROM
            pg_attribute attr
        JOIN
            pg_class c ON attr.attrelid = c.oid
        WHERE
            attr.attnotnull = true
            AND attr.attnum > 0
            AND c.relowner::regrole = current_user::regrole
    ) ORDER BY table_name;
GRANT SELECT ON SYS.USER_CONSTRAINTS TO PUBLIC;

/* *******************************************************************************************
                                         XXX_CONS_COLUMNS
* *******************************************************************************************/
CREATE OR REPLACE VIEW SYS.DBA_CONS_COLUMNS AS
    (
        SELECT
            SYS.ORA_CASE_TRANS(PG_GET_USERBYID(c.relowner)::VARCHAR2)::VARCHAR2(128) AS owner,
            SYS.ORA_CASE_TRANS(pc.conname::VARCHAR2)::VARCHAR2(128) AS constraint_name,
            SYS.ORA_CASE_TRANS(c.relname::VARCHAR2)::VARCHAR2(128) AS table_name,
            SYS.ORA_CASE_TRANS(pa.attname::VARCHAR2)::VARCHAR2(128) AS column_name,
            CASE
                WHEN pc.contype = 'c' THEN NULL
                ELSE subscript
            END::number AS position
        FROM
            pg_constraint pc
        JOIN pg_class c ON pc.conrelid = c.oid
        JOIN LATERAL generate_subscripts(pc.conkey, 1) AS subscript ON TRUE
        JOIN pg_attribute pa ON
            pa.attrelid = pc.conrelid
            AND pa.attnum = pc.conkey[subscript]
        WHERE
            pc.conrelid <> 0
    UNION ALL
        SELECT
            SYS.ORA_CASE_TRANS(PG_GET_USERBYID(c.relowner)::VARCHAR2)::VARCHAR2(128) AS owner,
            (SYS.ORA_CASE_TRANS((c.relname || '_' || attr.attname)::varchar2) || '_NOT_NULL')::varchar2(128) AS constraint_name,
            SYS.ORA_CASE_TRANS(c.relname::VARCHAR2)::VARCHAR2(128) AS table_name,
            SYS.ORA_CASE_TRANS(attr.attname::VARCHAR2)::VARCHAR2(128) AS column_name,
            attr.attnum::number AS position
        FROM
            pg_attribute attr
        LEFT JOIN
            pg_class c ON attr.attrelid = c.oid
        WHERE attr.attnotnull AND attr.attnum > 0
    ) ORDER BY table_name;
GRANT SELECT ON SYS.DBA_CONS_COLUMNS TO PUBLIC;

CREATE OR REPLACE VIEW SYS.ALL_CONS_COLUMNS AS
    (
        SELECT
            SYS.ORA_CASE_TRANS(PG_GET_USERBYID(c.relowner)::VARCHAR2)::VARCHAR2(128) AS owner,
            SYS.ORA_CASE_TRANS(pc.conname::VARCHAR2)::VARCHAR2(128) AS constraint_name,
            SYS.ORA_CASE_TRANS(c.relname::VARCHAR2)::VARCHAR2(128) AS table_name,
            SYS.ORA_CASE_TRANS(pa.attname::VARCHAR2)::VARCHAR2(128) AS column_name,
            CASE
                WHEN pc.contype = 'c' THEN NULL
                ELSE subscript
            END::number AS position
        FROM
            pg_constraint pc
        JOIN pg_class c ON pc.conrelid = c.oid
        JOIN LATERAL generate_subscripts(pc.conkey, 1) AS subscript ON TRUE
        JOIN pg_attribute pa ON
            pa.attrelid = pc.conrelid
            AND pa.attnum = pc.conkey[subscript]
        WHERE
            pc.conrelid <> 0
            AND (
                HAS_TABLE_PRIVILEGE(c.oid, 'SELECT')
                OR HAS_TABLE_PRIVILEGE(c.oid,'INSERT')
                OR HAS_TABLE_PRIVILEGE(c.oid, 'UPDATE')
                OR HAS_TABLE_PRIVILEGE(c.oid, 'DELETE')
                OR HAS_TABLE_PRIVILEGE(c.oid, 'TRUNCATE')
                OR HAS_TABLE_PRIVILEGE(c.oid, 'TRIGGER')
                OR HAS_TABLE_PRIVILEGE(c.oid, 'REFERENCES')
                )
    UNION ALL
        SELECT
            SYS.ORA_CASE_TRANS(PG_GET_USERBYID(c.relowner)::VARCHAR2)::VARCHAR2(128) AS owner,
            (SYS.ORA_CASE_TRANS((c.relname || '_' || attr.attname)::varchar2) || '_NOT_NULL')::varchar2(128) AS constraint_name,
            SYS.ORA_CASE_TRANS(c.relname::VARCHAR2)::VARCHAR2(128) AS table_name,
            SYS.ORA_CASE_TRANS(attr.attname::VARCHAR2)::VARCHAR2(128) AS column_name,
            attr.attnum::number AS position
        FROM
            pg_attribute attr
        LEFT JOIN
            pg_class c ON attr.attrelid = c.oid
        WHERE
            attr.attnotnull AND attr.attnum > 0
            AND (
                HAS_TABLE_PRIVILEGE(c.oid, 'SELECT')
                OR HAS_TABLE_PRIVILEGE(c.oid,'INSERT')
                OR HAS_TABLE_PRIVILEGE(c.oid, 'UPDATE')
                OR HAS_TABLE_PRIVILEGE(c.oid, 'DELETE')
                OR HAS_TABLE_PRIVILEGE(c.oid, 'TRUNCATE')
                OR HAS_TABLE_PRIVILEGE(c.oid, 'TRIGGER')
                OR HAS_TABLE_PRIVILEGE(c.oid, 'REFERENCES')
                )
    ) ORDER BY table_name;
GRANT SELECT ON SYS.ALL_CONS_COLUMNS TO PUBLIC;

CREATE OR REPLACE VIEW SYS.USER_CONS_COLUMNS AS
    (
        SELECT
            SYS.ORA_CASE_TRANS(PG_GET_USERBYID(c.relowner)::VARCHAR2)::VARCHAR2(128) AS owner,
            SYS.ORA_CASE_TRANS(pc.conname::VARCHAR2)::VARCHAR2(128) AS constraint_name,
            SYS.ORA_CASE_TRANS(c.relname::VARCHAR2)::VARCHAR2(128) AS table_name,
            SYS.ORA_CASE_TRANS(pa.attname::VARCHAR2)::VARCHAR2(128) AS column_name,
            CASE
                WHEN pc.contype = 'c' THEN NULL
                ELSE subscript
            END::number AS position
        FROM
            pg_constraint pc
        JOIN pg_class c ON pc.conrelid = c.oid
        JOIN LATERAL generate_subscripts(pc.conkey, 1) AS subscript ON TRUE
        JOIN pg_attribute pa ON
            pa.attrelid = pc.conrelid
            AND pa.attnum = pc.conkey[subscript]
        WHERE
            pc.conrelid <> 0
            AND c.relowner::regrole = current_user::regrole
    UNION ALL
        SELECT
            SYS.ORA_CASE_TRANS(PG_GET_USERBYID(c.relowner)::VARCHAR2)::VARCHAR2(128) AS owner,
            (SYS.ORA_CASE_TRANS((c.relname || '_' || attr.attname)::varchar2) || '_NOT_NULL')::varchar2(128) AS constraint_name,
            SYS.ORA_CASE_TRANS(c.relname::VARCHAR2)::VARCHAR2(128) AS table_name,
            SYS.ORA_CASE_TRANS(attr.attname::VARCHAR2)::VARCHAR2(128) AS column_name,
            attr.attnum::number AS position
        FROM
            pg_attribute attr
        LEFT JOIN
            pg_class c ON attr.attrelid = c.oid
        WHERE
            attr.attnotnull AND attr.attnum > 0
            AND c.relowner::regrole = current_user::regrole
    ) ORDER BY table_name;
GRANT SELECT ON SYS.USER_CONS_COLUMNS TO PUBLIC;

/* *******************************************************************************************
                                          XXX_TAB_PRIVS
* *******************************************************************************************/
/* Auxiliary function to query OID and ROLNAME from pg_authid */
CREATE OR REPLACE FUNCTION sys.get_auth_info(out oid, out text)
RETURNS SETOF RECORD SECURITY DEFINER AS
$$
    SELECT oid, rolname FROM pg_authid
$$ language sql;
GRANT EXECUTE ON FUNCTION sys.get_auth_info(out oid, out text) TO PUBLIC;

/* 
 * Auxiliary view describing the privilege informations of TABLE, VIEW, MATERIALIZED VIEW, SEQUENCE,
 * PACKAGE, PROCEDURE, FUNCTION, TYPE, LANGUAGE.
 */
CREATE OR REPLACE VIEW SYS.OBJECT_PRIVILEGES AS
    SELECT      -- include table, view, sequence, materialized view
        u_grantor.rolname AS grantor,
        grantee.rolname AS grantee,
        current_database() AS table_catalog,
        nc.nspname AS table_schema,
        c.relname AS table_name,
        c.prtype AS privilege_type,
        CASE WHEN
            -- object owner always has grant options
            pg_has_role(grantee.oid, c.relowner, 'USAGE')
            OR c.grantable
            THEN 'YES' ELSE 'NO' END AS is_grantable,
        CASE WHEN c.prtype = 'SELECT' THEN 'YES' ELSE 'NO' END AS with_hierarchy,
        CASE c.relkind
            WHEN 'r' THEN 'TABLE'
            WHEN 'v' THEN 'VIEW'
            WHEN 'f' THEN 'TABLE'
            WHEN 'p' THEN 'TABLE'
            WHEN 'm' THEN 'MATERIALIZED VIEW'
            WHEN 'S' THEN 'SEQUENCE'
            ELSE NULL
        END AS object_type,
        c.relowner AS owner,
        c.oid AS oid
    FROM (
            SELECT oid, relname, relnamespace, relkind, relowner, (aclexplode(coalesce(relacl, acldefault('r', relowner)))).* FROM pg_class
        ) AS c (oid, relname, relnamespace, relkind, relowner, grantor, grantee, prtype, grantable),
        pg_namespace nc,
        (SELECT * FROM sys.get_auth_info()) AS u_grantor (oid, rolname),
        (
            SELECT * FROM sys.get_auth_info()
            UNION ALL
            SELECT 0::oid, 'PUBLIC'
        ) AS grantee (oid, rolname)
    WHERE c.relnamespace = nc.oid
        AND c.relkind IN ('r', 'v', 'f', 'p', 'm', 'S')
        AND c.grantee = grantee.oid
        AND c.grantor = u_grantor.oid
        AND c.prtype IN ('INSERT', 'SELECT', 'UPDATE', 'DELETE', 'TRUNCATE', 'REFERENCES', 'TRIGGER')
UNION ALL
    SELECT      -- include package
        u_grantor.rolname AS grantor,
        grantee.rolname AS grantee,
        current_database() AS table_catalog,
        nc.nspname AS table_schema,
        c.pkgname AS table_name,
        c.prtype AS privilege_type,
        CASE WHEN
            -- object owner always has grant options
            pg_has_role(grantee.oid, c.pkgowner, 'USAGE')
            OR c.grantable
            THEN 'YES' ELSE 'NO' END AS is_grantable,
        CASE WHEN c.prtype = 'SELECT' THEN 'YES' ELSE 'NO' END AS with_hierarchy,
        'PACKAGE' AS object_type,
        c.pkgowner AS owner,
        c.oid AS oid
    FROM (
            SELECT oid, pkgname, pkgnamespace, pkgowner, (aclexplode(coalesce(pkgacl, acldefault('r', pkgowner)))).* FROM pg_package
        ) AS c (oid, pkgname, pkgnamespace, pkgowner, grantor, grantee, prtype, grantable),
        pg_namespace nc,
        (SELECT * FROM sys.get_auth_info()) AS u_grantor (oid, rolname),
        (
            SELECT * FROM sys.get_auth_info()
            UNION ALL
            SELECT 0::oid, 'PUBLIC'
        ) AS grantee (oid, rolname)
    WHERE c.pkgnamespace = nc.oid
        AND c.grantee = grantee.oid
        AND c.grantor = u_grantor.oid
        AND c.prtype IN ('EXECUTE')
UNION ALL
    SELECT      -- include function, procedure
        u_grantor.rolname AS grantor,
        grantee.rolname AS grantee,
        current_database() AS table_catalog,
        nc.nspname AS table_schema,
        c.proname AS table_name,
        c.prtype AS privilege_type,
        CASE WHEN
            -- object owner always has grant options
            pg_has_role(grantee.oid, c.proowner, 'USAGE')
            OR c.grantable
            THEN 'YES' ELSE 'NO' END AS is_grantable,
        CASE WHEN c.prtype = 'SELECT' THEN 'YES' ELSE 'NO' END AS with_hierarchy,
        CASE c.prokind
            WHEN 'f' THEN 'FUNCTION'
            WHEN 'p' THEN 'PROCEDURE'
            ELSE 'OTHER PROC TYPE'
        END AS object_type,
        c.proowner AS owner,
        c.oid AS oid
    FROM (
            SELECT oid, proname, pronamespace, prokind, proowner, (aclexplode(coalesce(proacl, acldefault('r', proowner)))).* FROM pg_proc
        ) AS c (oid, proname, pronamespace, prokind, proowner, grantor, grantee, prtype, grantable),
        pg_namespace nc,
        (SELECT * FROM sys.get_auth_info()) AS u_grantor (oid, rolname),
        (
            SELECT * FROM sys.get_auth_info()
            UNION ALL
            SELECT 0::oid, 'PUBLIC'
        ) AS grantee (oid, rolname)
    WHERE c.pronamespace = nc.oid
        AND c.grantee = grantee.oid
        AND c.grantor = u_grantor.oid
        AND c.prtype IN ('EXECUTE')
UNION ALL
    SELECT      -- include language
        u_grantor.rolname AS grantor,
        grantee.rolname AS grantee,
        current_database() AS table_catalog,
        'PUBLIC' AS table_schema,
        c.lanname AS table_name,
        c.prtype AS privilege_type,
        CASE WHEN
            -- object owner always has grant options
            pg_has_role(grantee.oid, c.lanowner, 'USAGE')
            OR c.grantable
            THEN 'YES' ELSE 'NO' END AS is_grantable,
        CASE WHEN c.prtype = 'SELECT' THEN 'YES' ELSE 'NO' END AS with_hierarchy,
        'LANGUAGE' AS object_type,
        c.lanowner AS owner,
        c.oid AS oid
    FROM (
            SELECT oid, lanname, lanowner, (aclexplode(coalesce(lanacl, acldefault('r', lanowner)))).* FROM pg_language
        ) AS c (oid, lanname, lanowner, grantor, grantee, prtype, grantable),
        (SELECT * FROM sys.get_auth_info()) AS u_grantor (oid, rolname),
        (
            SELECT * FROM sys.get_auth_info()
            UNION ALL
            SELECT 0::oid, 'PUBLIC'
        ) AS grantee (oid, rolname)
    WHERE c.grantee = grantee.oid
        AND c.grantor = u_grantor.oid
        AND c.prtype IN ('USAGE')
UNION ALL
    SELECT      -- include type
        u_grantor.rolname AS grantor,
        grantee.rolname AS grantee,
        current_database() AS table_catalog,
        nc.nspname AS table_schema,
        c.typname AS table_name,
        c.prtype AS privilege_type,
        CASE WHEN
            -- object owner always has grant options
            pg_has_role(grantee.oid, c.typowner, 'USAGE')
            OR c.grantable
            THEN 'YES' ELSE 'NO' END AS is_grantable,
        CASE WHEN c.prtype = 'SELECT' THEN 'YES' ELSE 'NO' END AS with_hierarchy,
        'TYPE' AS object_type,
        c.typowner AS owner,
        c.oid AS oid
    FROM (
            SELECT oid, typname, typnamespace, typowner, (aclexplode(coalesce(typacl, acldefault('r', typowner)))).* FROM pg_type
        ) AS c (oid, typname, typnamespace, typowner, grantor, grantee, prtype, grantable),
        pg_namespace nc,
        (SELECT * FROM sys.get_auth_info()) AS u_grantor (oid, rolname),
        (
            SELECT * FROM sys.get_auth_info()
            UNION ALL
            SELECT 0::oid, 'PUBLIC'
        ) AS grantee (oid, rolname)
    WHERE c.typnamespace = nc.oid
        AND c.grantee = grantee.oid
        AND c.grantor = u_grantor.oid
        AND c.prtype IN ('USAGE');
GRANT SELECT ON SYS.OBJECT_PRIVILEGES TO PUBLIC;

CREATE OR REPLACE VIEW SYS.DBA_TAB_PRIVS AS
    SELECT
        SYS.ORA_CASE_TRANS(objp.grantee::varchar2)::varchar2(128) AS grantee,
        SYS.ORA_CASE_TRANS((PG_GET_USERBYID(objp.owner))::varchar2)::varchar2(128) AS owner,
        SYS.ORA_CASE_TRANS(objp.table_name::varchar2)::varchar2(128) AS table_name,
        SYS.ORA_CASE_TRANS(objp.grantor::varchar2)::varchar2(128) AS grantor,
        objp.privilege_type::varchar2(40) AS privilege,
        objp.is_grantable::varchar2(3) AS grantable,
        objp.with_hierarchy::varchar2(3) AS hierarchy,
        'NO'::varchar2(3) AS common,
        object_type AS type,
        'NO'::varchar2(3) AS inherited
    FROM
        sys.object_privileges objp
    JOIN
        pg_namespace n ON objp.table_schema = n.nspname
    WHERE
        objp.grantee <> objp.grantor;
GRANT SELECT ON SYS.DBA_TAB_PRIVS TO PUBLIC;

CREATE OR REPLACE VIEW SYS.ALL_TAB_PRIVS AS
    SELECT
        SYS.ORA_CASE_TRANS(objp.grantor::varchar2)::varchar2(128) AS grantor,
        SYS.ORA_CASE_TRANS(objp.grantee::varchar2)::varchar2(128) AS grantee,
        SYS.ORA_CASE_TRANS(objp.table_schema::varchar2)::varchar2(128) AS table_schema,
        SYS.ORA_CASE_TRANS(objp.table_name::varchar2)::varchar2(128) AS table_name,
        objp.privilege_type::varchar2(40) AS privilege,
        objp.is_grantable::varchar2(3) AS grantable,
        objp.with_hierarchy::varchar2(3) AS hierarchy,
        'NO'::varchar2(3) AS common,
        object_type AS type,
        'NO'::varchar2(3) AS inherited
    FROM
        sys.object_privileges objp
    JOIN
        pg_namespace n ON objp.table_schema = n.nspname
    WHERE
        objp.grantee <> objp.grantor AND
        (
            CASE
                WHEN objp.object_type IN ('TABLE', 'VIEW', 'SEQUENCE', 'MATERIALIZED VIEW') THEN
                (
                    HAS_TABLE_PRIVILEGE(objp.oid, 'SELECT')
                    OR HAS_TABLE_PRIVILEGE(objp.oid,'INSERT')
                    OR HAS_TABLE_PRIVILEGE(objp.oid, 'UPDATE')
                    OR HAS_TABLE_PRIVILEGE(objp.oid, 'DELETE')
                    OR HAS_TABLE_PRIVILEGE(objp.oid, 'TRUNCATE')
                    OR HAS_TABLE_PRIVILEGE(objp.oid, 'TRIGGER')
                    OR HAS_TABLE_PRIVILEGE(objp.oid, 'REFERENCES')
                )
                ELSE
                (
                    objp.grantee = current_user
                    OR objp.grantor = current_user
                )
            END
        );
GRANT SELECT ON SYS.ALL_TAB_PRIVS TO PUBLIC;

CREATE OR REPLACE VIEW SYS.USER_TAB_PRIVS AS
    SELECT
        SYS.ORA_CASE_TRANS(objp.grantee::varchar2)::varchar2(128) AS grantee,
        SYS.ORA_CASE_TRANS((PG_GET_USERBYID(objp.owner))::varchar2)::varchar2(128) AS owner,
        SYS.ORA_CASE_TRANS(objp.table_name::varchar2)::varchar2(128) AS table_name,
        SYS.ORA_CASE_TRANS(objp.grantor::varchar2)::varchar2(128) AS grantor,
        objp.privilege_type::varchar2(40) AS privilege,
        objp.is_grantable::varchar2(3) AS grantable,
        objp.with_hierarchy::varchar2(3) AS hierarchy,
        'NO'::varchar2(3) AS common,
        object_type AS type,
        'NO'::varchar2(3) AS inherited
    FROM
        sys.object_privileges objp
    JOIN
        pg_namespace n ON objp.table_schema = n.nspname
    WHERE
        objp.grantee <> objp.grantor AND
        (objp.owner::regrole = current_user::regrole
        OR objp.grantee = current_user
        OR objp.grantor = current_user);

GRANT SELECT ON SYS.USER_TAB_PRIVS TO PUBLIC;
/* End - ReqID: RQ-SQL-SYSVIEW */

/* Begin - OA-REQ-2126 */
--
-- SESSION_PRIVS
--
CREATE OR REPLACE VIEW sys.session_privs AS
WITH RECURSIVE role_tree AS (
    SELECT oid
    FROM pg_roles
    WHERE rolname = current_user
    UNION
    SELECT m.roleid
    FROM pg_auth_members m
    JOIN role_tree r
      ON r.oid = m.member
),
effective_roles AS (
    SELECT *
    FROM pg_roles
    WHERE oid IN (SELECT oid FROM role_tree)
),
is_super AS (
    SELECT EXISTS (
        SELECT 1 FROM effective_roles WHERE rolsuper
    ) AS v
),
can_createrole AS (
    SELECT EXISTS (
        SELECT 1 FROM effective_roles
        WHERE rolcreaterole OR rolsuper
    ) AS v
),
has_schema_create AS (
    SELECT EXISTS (
		SELECT 1
		FROM pg_catalog.pg_namespace n
		WHERE n.nspname = current_schema()
		AND has_schema_privilege(n.oid, 'CREATE')
    ) AS v
)
SELECT SYS.ORA_CASE_TRANS(privilege::varchar2)::varchar2(40) AS privilege
FROM (
    /* ===================== SESSION / ROLE ===================== */
    SELECT 'CREATE USER' AS privilege
    WHERE (SELECT v FROM can_createrole)

    UNION ALL
    SELECT 'CREATE ROLE'
    WHERE (SELECT v FROM can_createrole)
    /* ===================== CREATE Object ===================== */

    UNION ALL
    SELECT 'CREATE TABLE'
    WHERE (SELECT v FROM has_schema_create)

    UNION ALL
    SELECT 'CREATE SEQUENCE'
    WHERE (SELECT v FROM has_schema_create)

    UNION ALL
    SELECT 'CREATE PROCEDURE'
    WHERE (SELECT v FROM has_schema_create)

    UNION ALL
    SELECT 'CREATE TRIGGER'
    WHERE (SELECT v FROM has_schema_create)

    UNION ALL
    SELECT 'CREATE TYPE'
    WHERE (SELECT v FROM has_schema_create)

    UNION ALL
    SELECT 'CREATE OPERATOR'
    WHERE (SELECT v FROM has_schema_create)

    UNION ALL
    SELECT 'CREATE VIEW'
    WHERE (SELECT v FROM has_schema_create)

    UNION ALL
    SELECT 'CREATE MATERIALIZED VIEW'
    WHERE (SELECT v FROM has_schema_create)

    UNION ALL
    SELECT 'CREATE SYNONYM'
    WHERE (SELECT v FROM has_schema_create)

    /* ===================== ANY TABLE ===================== */
    UNION ALL SELECT 'CREATE ANY TABLE' WHERE (SELECT v FROM is_super)
    UNION ALL SELECT 'ALTER ANY TABLE' WHERE (SELECT v FROM is_super)
    UNION ALL SELECT 'BACKUP ANY TABLE' WHERE (SELECT v FROM is_super)
    UNION ALL SELECT 'DROP ANY TABLE' WHERE (SELECT v FROM is_super)
    UNION ALL SELECT 'LOCK ANY TABLE' WHERE (SELECT v FROM is_super)
    UNION ALL SELECT 'COMMENT ANY TABLE' WHERE (SELECT v FROM is_super)
    UNION ALL SELECT 'SELECT ANY TABLE' WHERE (SELECT v FROM is_super)
    UNION ALL SELECT 'INSERT ANY TABLE' WHERE (SELECT v FROM is_super)
    UNION ALL SELECT 'UPDATE ANY TABLE' WHERE (SELECT v FROM is_super)
    UNION ALL SELECT 'DELETE ANY TABLE' WHERE (SELECT v FROM is_super)

    /* ===================== ANY INDEX ===================== */
    UNION ALL SELECT 'CREATE ANY INDEX' WHERE (SELECT v FROM is_super)
    UNION ALL SELECT 'ALTER ANY INDEX' WHERE (SELECT v FROM is_super)
    UNION ALL SELECT 'DROP ANY INDEX' WHERE (SELECT v FROM is_super)

    /* ===================== ANY SYNONYM ===================== */
    UNION ALL SELECT 'CREATE ANY SYNONYM' WHERE (SELECT v FROM is_super)
    UNION ALL SELECT 'DROP ANY SYNONYM' WHERE (SELECT v FROM is_super)

    /* ===================== ANY VIEW ===================== */
    UNION ALL SELECT 'CREATE ANY VIEW' WHERE (SELECT v FROM is_super)
    UNION ALL SELECT 'DROP ANY VIEW' WHERE (SELECT v FROM is_super)

    /* ===================== ANY SEQUENCE ===================== */
    UNION ALL SELECT 'CREATE ANY SEQUENCE' WHERE (SELECT v FROM is_super)
    UNION ALL SELECT 'ALTER ANY SEQUENCE' WHERE (SELECT v FROM is_super)
    UNION ALL SELECT 'DROP ANY SEQUENCE' WHERE (SELECT v FROM is_super)
    UNION ALL SELECT 'SELECT ANY SEQUENCE' WHERE (SELECT v FROM is_super)

    /* ===================== DATABASE LINK ===================== */
    UNION ALL SELECT 'CREATE DATABASE LINK' WHERE (SELECT v FROM is_super)
    UNION ALL SELECT 'CREATE PUBLIC DATABASE LINK' WHERE (SELECT v FROM is_super)
    UNION ALL SELECT 'DROP PUBLIC DATABASE LINK' WHERE (SELECT v FROM is_super)

    /* ===================== ROLE ===================== */
    UNION ALL SELECT 'DROP ANY ROLE' WHERE (SELECT v FROM can_createrole)
    UNION ALL SELECT 'GRANT ANY ROLE' WHERE (SELECT v FROM can_createrole)
    UNION ALL SELECT 'ALTER ANY ROLE' WHERE (SELECT v FROM can_createrole)

    /* ===================== ANY PROCEDURE ===================== */
    UNION ALL SELECT 'CREATE ANY PROCEDURE' WHERE (SELECT v FROM is_super)
    UNION ALL SELECT 'ALTER ANY PROCEDURE' WHERE (SELECT v FROM is_super)
    UNION ALL SELECT 'DROP ANY PROCEDURE' WHERE (SELECT v FROM is_super)
    UNION ALL SELECT 'EXECUTE ANY PROCEDURE' WHERE (SELECT v FROM is_super)

    /* ===================== ANY TRIGGER ===================== */
    UNION ALL SELECT 'CREATE ANY TRIGGER' WHERE (SELECT v FROM is_super)
    UNION ALL SELECT 'ALTER ANY TRIGGER' WHERE (SELECT v FROM is_super)
    UNION ALL SELECT 'DROP ANY TRIGGER' WHERE (SELECT v FROM is_super)

    /* ===================== ANY MATERIALIZED VIEW ===================== */
    UNION ALL SELECT 'CREATE ANY MATERIALIZED VIEW' WHERE (SELECT v FROM is_super)
    UNION ALL SELECT 'ALTER ANY MATERIALIZED VIEW' WHERE (SELECT v FROM is_super)
    UNION ALL SELECT 'DROP ANY MATERIALIZED VIEW' WHERE (SELECT v FROM is_super)

    /* ===================== TABLESPACE ===================== */
    UNION ALL SELECT 'CREATE TABLESPACE' WHERE (SELECT v FROM is_super)
    UNION ALL SELECT 'ALTER TABLESPACE'  WHERE (SELECT v FROM is_super)
    UNION ALL SELECT 'DROP TABLESPACE'   WHERE (SELECT v FROM is_super)
) s
ORDER BY privilege;
GRANT SELECT ON sys.session_privs TO PUBLIC;

--
-- DBA_REGISTRY
--
CREATE OR REPLACE VIEW sys.dba_registry AS
SELECT
    SYS.ORA_CASE_TRANS(e.extname::varchar2)::varchar2(30)    AS comp_id,
    e.extname::varchar2(255)                 AS comp_name,
    e.extversion::varchar2(30)               AS version,
    e.extversion::varchar2(30)               AS version_full,
    SYS.ORA_CASE_TRANS('VALID'::varchar2)::varchar2(11)    AS status,
    NULL::varchar2(20)                       AS modified,
    SYS.ORA_CASE_TRANS(n.nspname::varchar2)::varchar2(30)    AS namespace,
    SYS.ORA_CASE_TRANS(pg_get_userbyid(e.extowner)::varchar2)::varchar2(128) AS control,
    SYS.ORA_CASE_TRANS(n.nspname::varchar2)::varchar2(128)    AS schema,
    NULL::varchar2(61)                       AS procedure,
    NULL::varchar2(8)                     AS startup,
    NULL::varchar2(30)                       AS parent_id,
    NULL::varchar2(4000)                     AS other_schemas
FROM pg_catalog.pg_extension e
JOIN pg_catalog.pg_namespace n
    ON n.oid = e.extnamespace;
GRANT SELECT ON sys.dba_registry TO PUBLIC;

--
-- USER_REGISTRY
--
CREATE OR REPLACE VIEW sys.user_registry AS
SELECT * FROM sys.dba_registry WHERE control = CURRENT_USER;
GRANT SELECT ON sys.user_registry TO PUBLIC;
/* End - OA-REQ-2126 */

/* Begin - ReqID:SRS-SQL-PARTITION-TABLE */
CREATE OR REPLACE FUNCTION sys.ora_check_subpart_keys_consistent(rootoid Oid)
RETURNS boolean AS $$
DECLARE
    key_count integer;
    first_key int2vector;
    subpart_rec record;
BEGIN
    SELECT COUNT(*) INTO key_count
    FROM pg_inherits pi
    JOIN pg_partitioned_table ppt ON ppt.partrelid = pi.inhrelid
    WHERE pi.inhparent = rootoid;

    IF key_count = 0 THEN
        RETURN false;
    END IF;

    SELECT ppt.partattrs INTO first_key
    FROM pg_inherits pi
    JOIN pg_partitioned_table ppt ON ppt.partrelid = pi.inhrelid
    WHERE pi.inhparent = rootoid
    LIMIT 1;

    FOR subpart_rec IN
        SELECT ppt.partattrs
        FROM pg_inherits pi
        JOIN pg_partitioned_table ppt ON ppt.partrelid = pi.inhrelid
        WHERE pi.inhparent = rootoid
    LOOP
        IF subpart_rec.partattrs IS DISTINCT FROM first_key THEN
            RETURN false;
        END IF;
    END LOOP;

    RETURN true;
END;
$$ LANGUAGE plpgsql STABLE;

--
-- XXX_PART_TABLES
--
CREATE OR REPLACE VIEW SYS.DBA_PART_TABLES_INTERNAL AS
-- Oracle partitioned table info
SELECT
	c.relowner AS owner_id,
	c.oid AS obj_id,
	c.relnamespace AS namespace_id,
	sys.ora_case_trans(pg_get_userbyid(c.relowner)::varchar2)::varchar2(128) AS owner,
	sys.ora_case_trans(c.relname::varchar2)::varchar2(128) AS table_name,
	CASE ppt.partstrat
		WHEN 'r'::pg_catalog.char THEN 'RANGE'::varchar2(9)
		WHEN 'l'::pg_catalog.char THEN 'LIST'::varchar2(9)
		WHEN 'h'::pg_catalog.char THEN 'HASH'::varchar2(9)
		ELSE 'UNKNOWN'::varchar2(9)
	END::varchar2(9) AS partitioning_type,
	CASE opt.subpartstrat
		WHEN 'r'::pg_catalog.char THEN 'RANGE'::varchar2(9)
		WHEN 'l'::pg_catalog.char THEN 'LIST'::varchar2(9)
		WHEN 'h'::pg_catalog.char THEN 'HASH'::varchar2(9)
		WHEN 'n'::pg_catalog.char THEN 'NONE'::varchar2(9)
		ELSE 'UNKNOWN'::varchar2(9)
	END::varchar2(9) AS subpartitioning_type,
	CASE WHEN opt.interval_expr IS NOT NULL THEN 1048575::number
	ELSE
	(SELECT count(*) AS count
		FROM pg_ora_tab_partitions tp
		WHERE tp.partroot = opt.partrelid
		AND partlevel = 1)
	END::number AS partition_count,
	ora_def_subpartition_count(opt.partrelid)::number AS def_subpartition_count,
	ppt.partnatts::number AS partitioning_key_count,
	opt.subpartnatts::number AS subpartitioning_key_count,
	'VALID'::varchar2(8) AS status,
	CASE c.reltablespace
		WHEN 0 THEN
			(SELECT sys.ora_case_trans(spc.spcname::varchar2) FROM pg_database db, pg_tablespace spc
			 WHERE db.datname = current_database and db.dattablespace = spc.oid)::varchar2(30)
		ELSE
			(SELECT sys.ora_case_trans(spcname::varchar2)::varchar2(30)
			 FROM pg_tablespace spc WHERE spc.oid = c.reltablespace)
	END::varchar2(30) AS def_tablespace_name,
	NULL::number AS def_pct_free,
	NULL::number AS def_pct_used,
	NULL::number AS def_ini_trans,
	NULL::number AS def_max_trans,
	'DEFAULT'::varchar2(40) AS def_initial_extent,
	'DEFAULT'::varchar2(40) AS def_next_extent,
	'DEFAULT'::varchar2(40) AS def_min_extents,
	'DEFAULT'::varchar2(40) AS def_max_extents,
	'DEFAULT'::varchar2(40) AS def_max_size,
	'DEFAULT'::varchar2(40) AS def_pct_increase,
	NULL::number AS def_freelists,
	NULL::number AS def_freelist_groups,
	'YES'::varchar2(7) AS def_logging,
	'NONE'::varchar2(8) AS def_compression,
	NULL::varchar2(8) AS def_compress_for,
	'DEFAULT'::varchar2(7) AS def_buffer_pool,
	'DEFAULT'::varchar2(7) AS def_flash_cache,
	'DEFAULT'::varchar2(7) AS def_cell_flash_cache,
	NULL::varchar2(128) AS ref_ptn_constraint_name,
	pg_get_partinterval_string(c.oid)::varchar2(1000) AS interval,
	CASE opt.automatic
		WHEN TRUE THEN 'YES'::varchar2(3)
		ELSE 'NO'::varchar2(3)
	END::varchar2(3) AS autolist,
	NULL::varchar2(1000) AS interval_subpartition,
	'NO'::varchar2(3) AS autolist_subpartition,
	'NO'::varchar2(3) AS is_nested,
	'NONE'::varchar2(4) AS def_segment_creation,
	'ON'::varchar2(3) AS def_indexing,
	'NONE'::varchar2(8) AS def_inmemory,
	NULL::varchar2(8) AS def_inmemory_priority,
	NULL::varchar2(15) AS def_inmemory_distribute,
	NULL::varchar2(17) AS def_inmemory_compression,
	NULL::varchar2(13) AS def_inmemory_duplicate,
	'NO'::varchar2(3) AS def_read_only,
	NULL::varchar2(24) AS def_cellmemory,
	NULL::varchar2(12) AS def_inmemory_service,
	NULL::varchar2(1000) AS def_inmemory_service_name,
	CASE WHEN opt.automatic IS TRUE OR opt.interval_expr IS NOT NULL THEN 'YES'
	ELSE 'NO'
	END::varchar2(3) AS auto
FROM pg_class c
	JOIN pg_ora_part_tables opt ON c.oid = opt.partrelid
	JOIN pg_partitioned_table ppt ON c.oid = ppt.partrelid

UNION ALL
-- PostgreSQL partitioned table info
SELECT
	c.relowner AS owner_id,
	c.oid AS obj_id,
	c.relnamespace AS namespace_id,
	sys.ora_case_trans(pg_get_userbyid(c.relowner)::varchar2)::varchar2(128) AS owner,
	sys.ora_case_trans(c.relname::varchar2)::varchar2(128) AS table_name,
	CASE ppt.partstrat
		WHEN 'r'::pg_catalog.char THEN 'RANGE'::varchar2(9)
		WHEN 'l'::pg_catalog.char THEN 'LIST'::varchar2(9)
		WHEN 'h'::pg_catalog.char THEN 'HASH'::varchar2(9)
		ELSE 'UNKNOWN'::varchar2(9)
	END::varchar2(9) AS partitioning_type,
	CASE
		WHEN NOT EXISTS (
			SELECT 1 FROM pg_inherits pi
			JOIN pg_partitioned_table ppt2 ON ppt2.partrelid = pi.inhrelid
			WHERE pi.inhparent = c.oid
		) THEN 'NONE'::varchar2(9)
		WHEN (
			SELECT COUNT(DISTINCT ppt2.partstrat)
			FROM pg_inherits pi
			JOIN pg_partitioned_table ppt2 ON ppt2.partrelid = pi.inhrelid
			WHERE pi.inhparent = c.oid
		) > 1 THEN 'UNKNOWN'::varchar2(9)
		ELSE (
			SELECT CASE ppt2.partstrat
				WHEN 'r' THEN 'RANGE'::varchar2(9)
				WHEN 'l' THEN 'LIST'::varchar2(9)
				WHEN 'h' THEN 'HASH'::varchar2(9)
				ELSE 'UNKNOWN'::varchar2(9)
			END
			FROM pg_inherits pi
			JOIN pg_partitioned_table ppt2 ON ppt2.partrelid = pi.inhrelid
			WHERE pi.inhparent = c.oid
			LIMIT 1
		)
	END::varchar2(9) AS subpartitioning_type,
	(SELECT count(*)::number
	 FROM pg_inherits pi
	 WHERE pi.inhparent = c.oid) AS partition_count,
	0::number AS def_subpartition_count,
	ppt.partnatts::number AS partitioning_key_count,
	CASE
		WHEN NOT EXISTS (
			SELECT 1 FROM pg_inherits pi
			JOIN pg_partitioned_table ppt2 ON ppt2.partrelid = pi.inhrelid
			WHERE pi.inhparent = c.oid
		) THEN 0::number
		WHEN (
			SELECT COUNT(DISTINCT ppt2.partnatts)
			FROM pg_inherits pi
			JOIN pg_partitioned_table ppt2 ON ppt2.partrelid = pi.inhrelid
			WHERE pi.inhparent = c.oid
		) > 1 THEN NULL::number
		ELSE (
			SELECT ppt2.partnatts::number
			FROM pg_inherits pi
			JOIN pg_partitioned_table ppt2 ON ppt2.partrelid = pi.inhrelid
			WHERE pi.inhparent = c.oid
			LIMIT 1
		)
	END AS subpartitioning_key_count,
	'VALID'::varchar2(8) AS status,
	CASE c.reltablespace
		WHEN 0 THEN
			(SELECT sys.ora_case_trans(spc.spcname::varchar2) FROM pg_database db, pg_tablespace spc
			 WHERE db.datname = current_database and db.dattablespace = spc.oid)::varchar2(30)
		ELSE
			(SELECT sys.ora_case_trans(spcname::varchar2)::varchar2(30)
			 FROM pg_tablespace spc WHERE spc.oid = c.reltablespace)
	END::varchar2(30) AS def_tablespace_name,
	NULL::number AS def_pct_free,
	NULL::number AS def_pct_used,
	NULL::number AS def_ini_trans,
	NULL::number AS def_max_trans,
	'DEFAULT'::varchar2(40) AS def_initial_extent,
	'DEFAULT'::varchar2(40) AS def_next_extent,
	'DEFAULT'::varchar2(40) AS def_min_extents,
	'DEFAULT'::varchar2(40) AS def_max_extents,
	'DEFAULT'::varchar2(40) AS def_max_size,
	'DEFAULT'::varchar2(40) AS def_pct_increase,
	NULL::number AS def_freelists,
	NULL::number AS def_freelist_groups,
	'YES'::varchar2(7) AS def_logging,
	'NONE'::varchar2(8) AS def_compression,
	NULL::varchar2(8) AS def_compress_for,
	'DEFAULT'::varchar2(7) AS def_buffer_pool,
	'DEFAULT'::varchar2(7) AS def_flash_cache,
	'DEFAULT'::varchar2(7) AS def_cell_flash_cache,
	NULL::varchar2(128) AS ref_ptn_constraint_name,
	NULL::varchar2(1000) AS interval,
	'NO'::varchar2(3) AS autolist,
	NULL::varchar2(1000) AS interval_subpartition,
	'NO'::varchar2(3) AS autolist_subpartition,
	'NO'::varchar2(3) AS is_nested,
	'NONE'::varchar2(4) AS def_segment_creation,
	'ON'::varchar2(3) AS def_indexing,
	'NONE'::varchar2(8) AS def_inmemory,
	NULL::varchar2(8) AS def_inmemory_priority,
	NULL::varchar2(15) AS def_inmemory_distribute,
	NULL::varchar2(17) AS def_inmemory_compression,
	NULL::varchar2(13) AS def_inmemory_duplicate,
	'NO'::varchar2(3) AS def_read_only,
	NULL::varchar2(24) AS def_cellmemory,
	NULL::varchar2(12) AS def_inmemory_service,
	NULL::varchar2(1000) AS def_inmemory_service_name,
	'NO'::varchar2(3) AS auto
FROM pg_class c
	JOIN pg_partitioned_table ppt ON c.oid = ppt.partrelid
WHERE NOT EXISTS (
	SELECT 1 FROM pg_ora_part_tables opt WHERE opt.partrelid = c.oid
)
AND NOT EXISTS (
	SELECT 1 FROM pg_inherits pi WHERE pi.inhrelid = c.oid
);

