--
-- XXX_PART_KEY_COLUMNS
--
CREATE OR REPLACE VIEW SYS.DBA_PART_KEY_COLUMNS_INTERNAL AS
-- Partition keys info of Oracle partitionde tables
SELECT
	pk.ptowner AS owner_id,
	pk.ptschema AS namespace_id,
	pk.partrelid AS obj_id,
	a.attnum AS attno,
	sys.ora_case_trans(pg_get_userbyid(pk.ptowner)::varchar2)::varchar2(128) AS owner,
	sys.ora_case_trans(pk.ptname::varchar2)::varchar2(128) AS name,
	'TABLE'::char(5) AS object_type,
	CASE WHEN a.attname IS NULL THEN 'N/A'
	ELSE sys.ora_case_trans(a.attname::varchar2)
	END::varchar2(4000) AS column_name,
	(pk.pos + 1)::number AS column_position,
	NULL::number AS collated_column_id
FROM (SELECT ppt.partrelid,
			 ppt.partattrs,
			 generate_subscripts(ppt.partattrs, 1) AS pos,
			 c.relname AS ptname,
			 c.relnamespace AS ptschema,
			 c.relowner AS ptowner
	  FROM pg_partitioned_table ppt
		   JOIN pg_ora_part_tables opt ON ppt.partrelid = opt.partrelid
		   JOIN pg_class c ON c.oid = opt.partrelid
	 ) pk
	LEFT JOIN pg_attribute a ON a.attrelid = pk.partrelid AND a.attnum = pk.partattrs[pk.pos]

UNION ALL
-- Partition keys info of PostgreSQL partitioned tables
SELECT
	pk.ptowner AS owner_id,
	pk.ptschema AS namespace_id,
	pk.partrelid AS obj_id,
	a.attnum AS attno,
	sys.ora_case_trans(pg_get_userbyid(pk.ptowner)::varchar2)::varchar2(128) AS owner,
	sys.ora_case_trans(pk.ptname::varchar2)::varchar2(128) AS name,
	'TABLE'::char(5) AS object_type,
	CASE WHEN a.attname IS NULL THEN 'N/A'
	ELSE sys.ora_case_trans(a.attname::varchar2)
	END::varchar2(4000) AS column_name,
	(pk.pos + 1)::number AS column_position,
	NULL::number AS collated_column_id
FROM (SELECT ppt.partrelid,
			 ppt.partattrs,
			 generate_subscripts(ppt.partattrs, 1) AS pos,
			 c.relname AS ptname,
			 c.relnamespace AS ptschema,
			 c.relowner AS ptowner
	  FROM pg_partitioned_table ppt
		   JOIN pg_class c ON c.oid = ppt.partrelid
	  WHERE NOT EXISTS (SELECT 1 FROM pg_ora_part_tables opt WHERE opt.partrelid = ppt.partrelid)
		AND NOT EXISTS (SELECT 1 FROM pg_inherits pi WHERE pi.inhrelid = ppt.partrelid)
	 ) pk
	LEFT JOIN pg_attribute a ON a.attrelid = pk.partrelid AND a.attnum = pk.partattrs[pk.pos]
ORDER BY name, column_position;

CREATE OR REPLACE VIEW SYS.DBA_PART_KEY_COLUMNS AS
SELECT
	owner,
	name,
	object_type,
	column_name,
	column_position,
	collated_column_id
FROM DBA_PART_KEY_COLUMNS_INTERNAL
ORDER BY name, column_position;

GRANT SELECT ON SYS.DBA_PART_KEY_COLUMNS TO PUBLIC;

CREATE OR REPLACE VIEW SYS.ALL_PART_KEY_COLUMNS AS
SELECT
	owner,
	name,
	object_type,
	column_name,
	column_position,
	collated_column_id
FROM DBA_PART_KEY_COLUMNS_INTERNAL i
WHERE
	has_schema_privilege(i.namespace_id, 'USAGE'::text) AND 
	CASE WHEN i.attno IS NULL THEN 't'
	ELSE has_column_privilege(i.obj_id, i.attno, 'SELECT, INSERT, UPDATE, REFERENCES'::text)
	END = 't'
ORDER BY name, column_position;

GRANT SELECT ON SYS.ALL_PART_KEY_COLUMNS TO PUBLIC;

CREATE OR REPLACE VIEW SYS.USER_PART_KEY_COLUMNS AS
SELECT
	name,
	object_type,
	column_name,
	column_position,
	collated_column_id
FROM DBA_PART_KEY_COLUMNS_INTERNAL i
WHERE
	pg_get_userbyid(i.owner_id) = CURRENT_USER
ORDER BY name, column_position;

GRANT SELECT ON SYS.USER_PART_KEY_COLUMNS TO PUBLIC;

--
-- XXX_SUBPART_KEY_COLUMNS
--
CREATE OR REPLACE VIEW SYS.DBA_SUBPART_KEY_COLUMNS_INTERNAL AS
-- Subpartition keys info of Oracle partitioned tables
SELECT
	pk.ptowner AS owner_id,
	pk.ptschema AS namespace_id,
	pk.partrelid AS obj_id,
	a.attnum AS attno,
	sys.ora_case_trans(pg_get_userbyid(pk.ptowner)::varchar2)::varchar2(128) AS owner,
	sys.ora_case_trans(pk.ptname::varchar2)::varchar2(128) AS name,
	'TABLE'::char(5) AS object_type,
	CASE WHEN a.attname IS NULL THEN 'N/A'
	ELSE sys.ora_case_trans(a.attname::varchar2)
	END::varchar2(4000) AS column_name,
	(pk.pos + 1)::number AS column_position,
	NULL::number AS collated_column_id
FROM (SELECT opt.partrelid,
			 opt.subpartattrs,
			 generate_subscripts(opt.subpartattrs, 1) AS pos,
			 c.relname AS ptname,
			 c.relnamespace AS ptschema,
			 c.relowner AS ptowner
	  FROM pg_ora_part_tables opt
		   JOIN pg_class c ON c.oid = opt.partrelid
	 ) pk
	LEFT JOIN pg_attribute a ON a.attrelid = pk.partrelid AND a.attnum = pk.subpartattrs[pk.pos]

UNION ALL
-- Subpartition keys info of PostgreSQL partitioned tables
SELECT
	pk.root_owner AS owner_id,
	pk.ptschema AS namespace_id,
	pk.partrelid AS obj_id,
	a.attnum AS attno,
	sys.ora_case_trans(pg_get_userbyid(pk.root_owner)::varchar2)::varchar2(128) AS owner,
	sys.ora_case_trans(pk.root_name::varchar2)::varchar2(128) AS name,
	'TABLE'::char(5) AS object_type,
	CASE WHEN a.attname IS NULL THEN 'N/A'
	ELSE sys.ora_case_trans(a.attname::varchar2)
	END::varchar2(4000) AS column_name,
	(pk.pos + 1)::number AS column_position,
	NULL::number AS collated_column_id
FROM (SELECT subpart.partrelid,
			 subpart.partattrs,
			 generate_subscripts(subpart.partattrs, 1) AS pos,
			 c.relname AS ptname,
			 c.relnamespace AS ptschema,
			 c.relowner AS ptowner,
			 root_c.relname AS root_name,
			 root_c.relowner AS root_owner
	  FROM pg_partitioned_table subpart
		   JOIN pg_class c ON c.oid = subpart.partrelid
		   JOIN pg_inherits pi ON pi.inhrelid = subpart.partrelid
		   JOIN pg_class root_c ON root_c.oid = pi.inhparent
		   JOIN pg_partitioned_table root_ppt ON root_ppt.partrelid = root_c.oid
	  WHERE NOT EXISTS (SELECT 1 FROM pg_ora_part_tables opt WHERE opt.partrelid = root_c.oid)
		AND NOT EXISTS (SELECT 1 FROM pg_inherits pi2 WHERE pi2.inhrelid = root_c.oid)
		AND sys.ora_check_subpart_keys_consistent(root_c.oid)
		AND subpart.partrelid = (
			SELECT pi2.inhrelid
			FROM pg_inherits pi2
			WHERE pi2.inhparent = root_c.oid
			LIMIT 1
		)
	 ) pk
	LEFT JOIN pg_attribute a ON a.attrelid = pk.partrelid AND a.attnum = pk.partattrs[pk.pos]
ORDER BY name, column_position;

CREATE OR REPLACE VIEW SYS.DBA_SUBPART_KEY_COLUMNS AS
SELECT
	owner,
	name,
	object_type,
	column_name,
	column_position,
	collated_column_id
FROM DBA_SUBPART_KEY_COLUMNS_INTERNAL
ORDER BY name, column_position;

GRANT SELECT ON SYS.DBA_SUBPART_KEY_COLUMNS TO PUBLIC;

CREATE OR REPLACE VIEW SYS.ALL_SUBPART_KEY_COLUMNS AS
SELECT
	owner,
	name,
	object_type,
	column_name,
	column_position,
	collated_column_id
FROM DBA_SUBPART_KEY_COLUMNS_INTERNAL i
WHERE
	has_schema_privilege(i.namespace_id, 'USAGE'::text) AND 
	CASE WHEN i.attno IS NULL THEN 't'
	ELSE has_column_privilege(i.obj_id, i.attno, 'SELECT, INSERT, UPDATE, REFERENCES'::text)
	END = 't'
ORDER BY name, column_position;

GRANT SELECT ON SYS.ALL_SUBPART_KEY_COLUMNS TO PUBLIC;

CREATE OR REPLACE VIEW SYS.USER_SUBPART_KEY_COLUMNS AS
SELECT
	name,
	object_type,
	column_name,
	column_position,
	collated_column_id
FROM DBA_SUBPART_KEY_COLUMNS_INTERNAL i
WHERE
	pg_get_userbyid(i.owner_id) = CURRENT_USER
ORDER BY name, column_position;

GRANT SELECT ON SYS.USER_SUBPART_KEY_COLUMNS TO PUBLIC;

--
-- XXX_SUBPARTITION_TEMPLATES
--
CREATE OR REPLACE VIEW SYS.DBA_SUBPARTITION_TEMPLATES_INTERNAL AS
SELECT
	ptmp.ptowner AS owner_id,
	ptmp.partrelid AS obj_id,
	ptmp.ptschema AS namespace_id,
	sys.ora_case_trans(pg_get_userbyid(ptmp.ptowner)::varchar2)::varchar2(128) AS user_name,
	sys.ora_case_trans(ptmp.ptname::varchar2)::varchar2(128) AS table_name,
	sys.ora_case_trans(ptmp.name::varchar2)::varchar2(132) AS subpartition_name,
	ptmp.position::number AS subpartition_position,
	sys.ora_case_trans(ptmp.tablespace::varchar2)::varchar2(30) AS tablespace_name,
	ptmp.highbound::text AS high_bound,
	'NONE'::varchar2(4) AS compression,
	'NONE'::varchar2(4) AS indexing,
	'NONE'::varchar2(4) AS read_only
FROM (SELECT opt.partrelid,
			 c.relowner AS ptowner,
			 c.relnamespace AS ptschema,
			 c.relname AS ptname,
			 t.name,
			 t.position,
			 t.tablespace,
			 t.highbound
	  FROM pg_ora_part_tables opt
		   JOIN pg_class c ON c.oid = opt.partrelid,
		   ora_get_subpartition_templates(opt.partrelid) t
	 ) ptmp
ORDER BY table_name, subpartition_position;

CREATE OR REPLACE VIEW SYS.DBA_SUBPARTITION_TEMPLATES AS
SELECT
	user_name,
	table_name,
	subpartition_name,
	subpartition_position,
	tablespace_name,
	high_bound,
	compression,
	indexing,
	read_only
FROM DBA_SUBPARTITION_TEMPLATES_INTERNAL
ORDER BY table_name, subpartition_position;

GRANT SELECT ON SYS.DBA_SUBPARTITION_TEMPLATES TO PUBLIC;

CREATE OR REPLACE VIEW SYS.ALL_SUBPARTITION_TEMPLATES AS
SELECT
	user_name,
	table_name,
	subpartition_name,
	subpartition_position,
	tablespace_name,
	high_bound,
	compression,
	indexing,
	read_only
FROM DBA_SUBPARTITION_TEMPLATES_INTERNAL i
WHERE
	has_schema_privilege(i.namespace_id, 'USAGE'::text)
	AND has_table_privilege(i.obj_id, 'SELECT, INSERT, UPDATE, DELETE, TRUNCATE, REFERENCES, TRIGGER'::text)
ORDER BY table_name, subpartition_position;

GRANT SELECT ON SYS.ALL_SUBPARTITION_TEMPLATES TO PUBLIC;

CREATE OR REPLACE VIEW SYS.USER_SUBPARTITION_TEMPLATES AS
SELECT
	table_name,
	subpartition_name,
	subpartition_position,
	tablespace_name,
	high_bound,
	compression,
	indexing,
	read_only
FROM DBA_SUBPARTITION_TEMPLATES_INTERNAL i
WHERE
	pg_get_userbyid(i.owner_id) = CURRENT_USER
ORDER BY table_name, subpartition_position;

GRANT SELECT ON SYS.USER_SUBPARTITION_TEMPLATES TO PUBLIC;
/* End - ReqID:SRS-SQL-PARTITION-TABLE */

/* Begin - ReqID:SRS-SQL-SYSVIEW */
----------------------------------------------------------
-- V$ DYNAMIC PERFORMANCE VIEWS
----------------------------------------------------------

-- V$SESSION
CREATE OR REPLACE VIEW SYS.V$SESSION AS
SELECT
    NULL::RAW(8) AS SADDR,
    PSGAE.SID::NUMBER AS SID,
    PS.PID::NUMBER AS SERIAL#,
    0::NUMBER AS AUDSID,
    PGSI.PADDR::RAW(8) AS PADDR,
    PS.USESYSID::BIGINT::NUMBER AS USER#,
    PS.USENAME::VARCHAR2(128) AS USERNAME,
    0::NUMBER AS COMMAND,
    2147483644::NUMBER AS OWNERID,
    NULL::VARCHAR2(16) AS TADDR,
    NULL::VARCHAR2(16) AS LOCKWAIT,
    CASE
        WHEN PS.STATE IN ('active', 'fastpath function call') THEN 'ACTIVE'
        WHEN PS.STATE = 'disabled' THEN 'UNKNOWN'
        ELSE 'INACTIVE'
    END::VARCHAR2(8) AS STATUS,
    'DEDICATED'::VARCHAR2(9) AS SERVER,
    NULL::NUMBER AS SCHEMA#,
    NULL::VARCHAR2(128) AS SCHEMANAME,
    PGSI.OSUSER::VARCHAR2(128) AS OSUSER,
    NULL::VARCHAR2(24) AS PROCESS,
    PSGAE.CLIENT_OSNAME::VARCHAR2(64) AS MACHINE,
    PS.CLIENT_PORT::NUMBER AS PORT,
    'UNKNOWN'::VARCHAR2(30) AS TERMINAL,
    PS.APPLICATION_NAME::VARCHAR2(84) AS PROGRAM,
    CASE
        WHEN PS.BACKEND_TYPE = 'client backend' THEN 'USER'
        ELSE 'BACKGROUND'
    END::VARCHAR2(10) AS TYPE,
    '\x0000000000000000'::RAW(8) AS SQL_ADDRESS,
    ('X' || RIGHT(MD5(PS.QUERY), 8))::BIT(32)::BIGINT::NUMBER AS SQL_HASH_VALUE,
    PS.QUERY_ID::VARCHAR2(19) AS SQL_ID,
    0::NUMBER AS SQL_CHILD_NUMBER,
    PS.QUERY_START::PG_CATALOG.DATE AS SQL_EXEC_START,
    CASE WHEN PS.STATE = 'active'
        THEN ( 'X' || RIGHT(MD5(PS.QUERY_ID || PL.VIRTUALXID), 8))::BIT(32)::BIGINT
        ELSE NULL
    END::NUMBER AS SQL_EXEC_ID,
    '\x0000000000000000'::RAW(8) AS PREV_SQL_ADDR,
    0::NUMBER AS PREV_HASH_VALUE,
    NULL::VARCHAR2(13) AS PREV_SQL_ID,
    0::NUMBER AS PREV_CHILD_NUMBER,
    NULL::PG_CATALOG.DATE AS PREV_EXEC_START,
    NULL::NUMBER AS PREV_EXEC_ID,
    PGSI.PLSQL_ENTRY_OBJECT_ID::BIGINT::NUMBER AS PLSQL_ENTRY_OBJECT_ID,
    PGSI.PLSQL_ENTRY_SUBPROGRAM_ID::NUMBER AS PLSQL_ENTRY_SUBPROGRAM_ID,
    PGSI.PLSQL_OBJECT_ID::BIGINT::NUMBER AS PLSQL_OBJECT_ID,
    PGSI.PLSQL_SUBPROGRAM_ID::NUMBER AS PLSQL_SUBPROGRAM_ID,
    NULL::VARCHAR2(64) AS MODULE,
    0::NUMBER AS MODULE_HASH,
    NULL::VARCHAR2(64) AS ACTION,
    0::NUMBER AS ACTION_HASH,
    NULL::VARCHAR2(64) AS CLIENT_INFO,
    0::NUMBER AS FIXED_TABLE_SEQUENCE,
    -1::NUMBER AS ROW_WAIT_OBJ#,
    0::NUMBER AS ROW_WAIT_FILE#,
    0::NUMBER AS ROW_WAIT_BLOCK#,
    0::NUMBER AS ROW_WAIT_ROW#,
    0::NUMBER AS TOP_LEVEL_CALL#,
    PS.BACKEND_START::PG_CATALOG.DATE AS LOGON_TIME,
    0::NUMBER AS LAST_CALL_ET,
    'NO'::VARCHAR2(3) AS PDML_ENABLED,
    'NONE'::VARCHAR2(13) AS FAILOVER_TYPE,
    'NONE'::VARCHAR2(10) AS FAILOVER_METHOD,
    'NO'::VARCHAR2(3) AS FAILED_OVER,
    PGR.RRRSGNAME::VARCHAR2(32) AS RESOURCE_CONSUMER_GROUP,
    'DISABLED'::VARCHAR2(8) AS PDML_STATUS,
    'DISABLED'::VARCHAR2(8) AS PDDL_STATUS,
    'DISABLED'::VARCHAR2(8) AS PQ_STATUS,
    0::NUMBER AS CURRENT_QUEUE_DURATION,
    NULL::VARCHAR2(64) AS CLIENT_IDENTIFIER,
    CASE
        WHEN 0 = ANY(BLOCKING_INFO.BLOCKING_PIDS) THEN 'UNKNOWN'
        WHEN BLOCKING_INFO.BLOCKING_PIDS = '{}' THEN 'NO HOLDER'
        ELSE 'VALID'
    END::VARCHAR2(11) AS BLOCKING_SESSION_STATUS,
    NULL::NUMBER AS BLOCKING_INSTANCE,
    BLOCKING_INFO.BLOCKING_PIDS[1]::NUMBER AS BLOCKING_SESSION,
    NULL::VARCHAR2(11) AS FINAL_BLOCKING_SESSION_STATUS,
    NULL::NUMBER AS FINAL_BLOCKING_INSTANCE,
    NULL::NUMBER AS FINAL_BLOCKING_SESSION,
    0::NUMBER AS SEQ#,
    NULL::NUMBER AS EVENT#,
    PS.WAIT_EVENT::VARCHAR2(64) AS EVENT,
    NULL::VARCHAR2(64) AS P1TEXT,
    0::NUMBER AS P1,
    '\x0000000000000000'::RAW(8) AS P1RAW,
    NULL::VARCHAR2(64) AS P2TEXT,
    0::NUMBER AS P2,
    '\x0000000000000000'::RAW(8) AS P2RAW,
    NULL::VARCHAR2(64) AS P3TEXT,
    0::NUMBER AS P3,
    '\x0000000000000000'::RAW(8) AS P3RAW,
    CASE
        WHEN PS.WAIT_EVENT_TYPE IS NULL THEN 0
        WHEN PS.WAIT_EVENT_TYPE = 'LWLock' THEN 1
        WHEN PS.WAIT_EVENT_TYPE = 'Lock' THEN 2
        WHEN PS.WAIT_EVENT_TYPE = 'BufferPin' THEN 3
        WHEN PS.WAIT_EVENT_TYPE = 'Activity' THEN 4
        WHEN PS.WAIT_EVENT_TYPE = 'Client' THEN 5
        WHEN PS.WAIT_EVENT_TYPE = 'Extension' THEN 6
        WHEN PS.WAIT_EVENT_TYPE = 'IPC' THEN 7
        WHEN PS.WAIT_EVENT_TYPE = 'Timeout' THEN 8
        WHEN PS.WAIT_EVENT_TYPE = 'IO' THEN 9
        WHEN PS.WAIT_EVENT_TYPE = 'InjectionPoint' THEN 10
        ELSE -1
    END::NUMBER AS WAIT_CLASS_ID,
    CASE
        WHEN PS.WAIT_EVENT_TYPE IS NULL THEN 0
        WHEN PS.WAIT_EVENT_TYPE = 'LWLock' THEN 1
        WHEN PS.WAIT_EVENT_TYPE = 'Lock' THEN 2
        WHEN PS.WAIT_EVENT_TYPE = 'BufferPin' THEN 3
        WHEN PS.WAIT_EVENT_TYPE = 'Activity' THEN 4
        WHEN PS.WAIT_EVENT_TYPE = 'Client' THEN 5
        WHEN PS.WAIT_EVENT_TYPE = 'Extension' THEN 6
        WHEN PS.WAIT_EVENT_TYPE = 'IPC' THEN 7
        WHEN PS.WAIT_EVENT_TYPE = 'Timeout' THEN 8
        WHEN PS.WAIT_EVENT_TYPE = 'IO' THEN 9
        WHEN PS.WAIT_EVENT_TYPE = 'InjectionPoint' THEN 10
        ELSE -1
    END::NUMBER AS WAIT_CLASS#,
    CASE
        WHEN PS.WAIT_EVENT_TYPE IS NULL THEN 'Idle'
        ELSE PS.WAIT_EVENT_TYPE
    END::VARCHAR2(64) AS WAIT_CLASS,
    0::NUMBER AS WAIT_TIME,
    0::NUMBER AS SECONDS_IN_WAIT,
    'WAITING'::VARCHAR2(19) AS STATE,
    NULL::NUMBER AS WAIT_TIME_MICRO,
    NULL::NUMBER AS TIME_REMAINING_MICRO,
    NULL::NUMBER AS TOTAL_TIME_WAITED_MICRO,
    NULL::NUMBER AS HEUR_TIME_WAITED_MICRO,
    NULL::NUMBER AS TIME_SINCE_LAST_WAIT_MICRO,
    NULL::VARCHAR2(64) AS SERVICE_NAME,
    'DISABLED'::VARCHAR2(8) AS SQL_TRACE,
    'FALSE'::VARCHAR2(5) AS SQL_TRACE_WAITS,
    'FALSE'::VARCHAR2(5) AS SQL_TRACE_BINDS,
    'FIRST EXEC'::VARCHAR2(10) AS SQL_TRACE_PLAN_STATS,
    NULL::NUMBER AS SESSION_EDITION_ID,
    NULL::RAW(8) AS CREATOR_ADDR,
    NULL::NUMBER AS CREATOR_SERIAL#,
    NULL::VARCHAR2(64) AS ECID,
    0::NUMBER AS SQL_TRANSLATION_PROFILE_ID,
    0::NUMBER AS PGA_TUNABLE_MEM,
    'DISABLED'::VARCHAR2(8) AS SHARD_DDL_STATUS,
    0::NUMBER AS CON_ID,
    NULL::VARCHAR2(1024) AS EXTERNAL_NAME,
    'FALSE'::VARCHAR2(5) AS PLSQL_DEBUGGER_CONNECTED
FROM PG_CATALOG.PG_STAT_ACTIVITY PS
    CROSS JOIN LATERAL PG_CATALOG.PG_BLOCKING_PIDS(PS.PID) AS BLOCKING_INFO(BLOCKING_PIDS)
    LEFT JOIN PG_CATALOG.PG_STAT_GET_ACTIVITY_EXT(NULL) PSGAE ON (PS.PID = PSGAE.PID)
    LEFT JOIN PG_CATALOG.PG_GET_SESSION_INFO(NULL) PGSI ON (PS.PID = PGSI.PID)
    LEFT JOIN PG_CATALOG.PG_LOCKS PL ON (PS.PID = PL.PID AND PL.LOCKTYPE='virtualxid')
    LEFT JOIN PG_CATALOG.PG_RESGROUP_ROLE PGR ON (PS.USENAME = PGR.RRROLNAME)
    WHERE PS.DATNAME = PG_CATALOG.CURRENT_DATABASE;

-- V$PROCESS
CREATE OR REPLACE VIEW SYS.V$PROCESS AS
SELECT
    PGSI.PADDR::RAW(8) AS ADDR,
    NULL::NUMBER AS PID,
    PS.PID::VARCHAR2(24) AS SOSID,
    PS.PID::VARCHAR2(24) AS SPID,
    NULL::VARCHAR2(24) AS STID,
    'PROCESS'::VARCHAR2(10) AS EXECUTION_TYPE,
    PS.BACKEND_TYPE::VARCHAR2(256) AS PNAME,
    PS.USENAME::VARCHAR2(15) AS USERNAME,
    0::NUMBER AS SERIAL#,
    'UNKNOWN'::VARCHAR2(30) AS TERMINAL,
    PS.APPLICATION_NAME::VARCHAR2(84) AS PROGRAM,
    NULL::VARCHAR2(255) AS TRACEID,
    NULL::VARCHAR2(513) AS TRACEFILE,
    1::VARCHAR2(1) AS BACKGROUND,
    NULL::VARCHAR2(16) AS LATCHWAIT,
    NULL::VARCHAR2(16) AS LATCHSPIN,
    NULL::NUMBER AS PGA_USED_MEM,
    NULL::NUMBER AS PGA_ALLOC_MEM,
    NULL::NUMBER AS PGA_FREEABLE_MEM,
    NULL::NUMBER AS PGA_MAX_MEM,
    NULL::NUMBER AS NUMA_DEFAULT,
    NULL::NUMBER AS NUMA_CURR,
    PGSI.CPU_USED::NUMBER AS CPU_USED,
    0::NUMBER AS CON_ID
FROM PG_CATALOG.PG_STAT_ACTIVITY PS
    LEFT JOIN PG_CATALOG.PG_GET_SESSION_INFO(NULL) PGSI ON (PS.PID = PGSI.PID);

-- V$PARAMETER
CREATE OR REPLACE VIEW SYS.V$PARAMETER AS
SELECT
    ROWNUM::NUMBER AS NUM,
    PS.NAME::VARCHAR2(80) AS NAME,
    CASE
        WHEN PS.VARTYPE = 'bool' THEN 1
        WHEN PS.VARTYPE = 'string' THEN 2
        WHEN PS.VARTYPE = 'integer' THEN 3
        WHEN PS.VARTYPE = 'enum' THEN 4
        WHEN PS.VARTYPE = 'real' THEN 5
        ELSE -1
    END::NUMBER AS TYPE,
    PS.SETTING::VARCHAR2(4000) AS VALUE,
    PS.SETTING::VARCHAR2(4000) AS DISPLAY_VALUE,
    PS.BOOT_VAL::VARCHAR2(255) AS DEFAULT_VALUE,
    CASE
        WHEN PS.SETTING IS NOT DISTINCT FROM PS.BOOT_VAL THEN 'TRUE'
        ELSE 'FALSE'
    END::VARCHAR2(9) AS ISDEFAULT,
    CASE
        WHEN PS.CONTEXT IN ('user', 'superuser') THEN 'TRUE'
        ELSE 'FALSE'
    END::VARCHAR2(5) AS ISSES_MODIFIABLE,
    CASE
        WHEN PS.CONTEXT IN ('user', 'superuser', 'sighup') THEN 'IMMEDIATE'
        WHEN PS.CONTEXT IN ('postmaster', 'internal') THEN 'FALSE'
        ELSE 'DEFERRED'
    END::VARCHAR2(9) AS ISSYS_MODIFIABLE,
    'FALSE'::VARCHAR2(5) AS ISPDB_MODIFIABLE,
    'FALSE'::VARCHAR2(5) AS ISINSTANCE_MODIFIABLE,
    PGPM.ISMODIFIED::VARCHAR2(10) AS ISMODIFIED,
    'FALSE'::VARCHAR2(5) AS ISADJUSTED,
    'FALSE'::VARCHAR2(5) AS ISDEPRECATED,
    CASE
        WHEN PS.CONTEXT IN ('postmaster', 'internal') THEN 'TRUE'
        ELSE 'FALSE'
    END::VARCHAR2(5) AS ISBASIC,
    PS.SHORT_DESC::VARCHAR2(255) AS DESCRIPTION,
    PS.EXTRA_DESC::VARCHAR2(255) AS UPDATE_COMMENT,
    ('X' || RIGHT(MD5(PS.NAME), 8))::BIT(32)::BIGINT::NUMBER AS HASH,
    0::NUMBER AS CON_ID
FROM PG_CATALOG.PG_SETTINGS PS, PG_CATALOG.PG_GET_PARAMETER_MODIFY_STATUS(PS.NAME) AS PGPM(NAME, ISMODIFIED) ORDER BY PS.NAME;

-- V$PARAMETER2
CREATE OR REPLACE VIEW SYS.V$PARAMETER2 AS
SELECT
    ROWNUM::NUMBER AS NUM,
    PS.NAME::VARCHAR2(80) AS NAME,
    CASE
        WHEN PS.VARTYPE = 'bool' THEN 1
        WHEN PS.VARTYPE = 'string' THEN 2
        WHEN PS.VARTYPE = 'integer' THEN 3
        WHEN PS.VARTYPE = 'enum' THEN 4
        WHEN PS.VARTYPE = 'real' THEN 5
        ELSE -1
    END::NUMBER AS TYPE,
    PS.SETTING::VARCHAR2(4000) AS VALUE,
    PS.SETTING::VARCHAR2(4000) AS DISPLAY_VALUE,
    CASE
        WHEN PS.SETTING IS NOT DISTINCT FROM PS.BOOT_VAL THEN 'TRUE'
        ELSE 'FALSE'
    END::VARCHAR2(6) AS ISDEFAULT,
    CASE
        WHEN PS.CONTEXT IN ('user', 'superuser') THEN 'TRUE'
        ELSE 'FALSE'
    END::VARCHAR2(5) AS ISSES_MODIFIABLE,
    CASE
        WHEN PS.CONTEXT IN ('user', 'superuser', 'sighup') THEN 'IMMEDIATE'
        WHEN PS.CONTEXT IN ('postmaster', 'internal') THEN 'FALSE'
        ELSE 'DEFERRED'
    END::VARCHAR2(9) AS ISSYS_MODIFIABLE,
    'FALSE'::VARCHAR2(5) AS ISPDB_MODIFIABLE,
    'FALSE'::VARCHAR2(5) AS ISINSTANCE_MODIFIABLE,
    PGPM.ISMODIFIED::VARCHAR2(10) AS ISMODIFIED,
    'FALSE'::VARCHAR2(5) AS ISADJUSTED,
    'FALSE'::VARCHAR2(5) AS ISDEPRECATED,
    CASE
        WHEN PS.CONTEXT IN ('postmaster', 'internal') THEN 'TRUE'
        ELSE 'FALSE'
    END::VARCHAR2(5) AS ISBASIC,
    PS.SHORT_DESC::VARCHAR2(255) AS DESCRIPTION,
    CASE
        WHEN PS.VARTYPE='enum' AND PS.ENUMVALS IS NOT NULL
            THEN ARRAY_POSITION(PS.ENUMVALS, PS.SETTING)
        ELSE NULL
    END::NUMBER AS ORDINAL,
    PS.EXTRA_DESC::VARCHAR2(255) AS UPDATE_COMMENT,
    0::NUMBER AS CON_ID
FROM PG_CATALOG.PG_SETTINGS PS, PG_CATALOG.PG_GET_PARAMETER_MODIFY_STATUS(PS.NAME) AS PGPM(NAME, ISMODIFIED) ORDER BY PS.NAME;
/* End - ReqID:SRS-SQL-SYSVIEW */